DO $$
DECLARE matched integer; foreign_questions integer;
BEGIN
    SELECT count(*) INTO matched FROM pool_question_text c
    JOIN speed_reading.reading_texts t ON t.id = c.id AND NOT t.is_deleted AND md5(t.content) = c.content_md5;
    IF matched <> 79 THEN
        RAISE EXCEPTION 'pool-questions/v2: % of 79 texts match; nothing changed', matched;
    END IF;
    SELECT count(*) INTO foreign_questions FROM speed_reading.reading_questions q JOIN pool_question_text c ON c.id = q.reading_text_id
    WHERE NOT q.is_deleted AND q.created_by IS DISTINCT FROM 'pool-questions-v2';
    IF foreign_questions <> 0 THEN
        RAISE EXCEPTION 'pool-questions/v2: % other question(s) already exist on these texts; nothing changed', foreign_questions;
    END IF;
END $$;

CREATE TEMP TABLE pool_question (
    id uuid PRIMARY KEY, reading_text_id uuid NOT NULL, question_text text NOT NULL, type integer NOT NULL,
    bloom_level integer NOT NULL, difficulty_level integer NOT NULL, explanation text NOT NULL,
    option_a text NOT NULL, option_b text NOT NULL, option_c text NOT NULL, option_d text NOT NULL,
    correct_answer text NOT NULL, order_index integer NOT NULL
) ON COMMIT DROP;
INSERT INTO pool_question
    (id, reading_text_id, question_text, type, bloom_level, difficulty_level, explanation,
     option_a, option_b, option_c, option_d, correct_answer, order_index)
VALUES
    ('d7b50000-0000-5000-8000-000000000001'::uuid, '03c8f2fe-9048-5e23-8d11-a51ccfa21be0'::uuid, 'Yazar örümcekleri neden mühendise benzetir?', 2, 4, 5, 'İlk paragrafa göre ağlar rastgele görünse de dikkatli bir planın ürünüdür; örümcekler bu yüzden mühendis gibi çalışır.',
     'Ağlarını yalnızca sabahları kurdukları için', 'Ağlarını parlak çiy damlalarıyla süsledikleri için', 'Ağlarını belli bir plana göre kurdukları için', 'Ağlarını en sağlam dallara kurdukları için', 'C', 0),
    ('d7b50000-0000-5000-8000-000000000002'::uuid, '03c8f2fe-9048-5e23-8d11-a51ccfa21be0'::uuid, 'Metne göre örümcekleri böceklerden ayıran nedir?', 1, 1, 5, 'Böceklerin altı bacağı ve üç bölümlü vücudu vardır; örümceklerin ise sekiz bacağı ve iki bölümlü vücudu.',
     'Bacak sayıları ile gövde yapıları', 'Kanatları ile antenlerinin sayısı', 'Yapışkan ipek üretebilmeleri', 'Göz sayıları ile vücut renkleri', 'A', 1),
    ('d7b50000-0000-5000-8000-000000000003'::uuid, '03c8f2fe-9048-5e23-8d11-a51ccfa21be0'::uuid, 'Örümcek kendi ağına neden takılmaz?', 1, 2, 5, 'Örümcek ağda dolaşırken çoğunlukla yapışkan olmayan ipliklere basar; böylece kendi tuzağına takılmaz.',
     'Ağın kuru tellerinde yürüdüğü için', 'Bacakları ipekle kaplı olduğu için', 'Ağın ortasında hiç kımıldamadığı için', 'İplikler onun ağırlığında kopmadığı için', 'A', 2),
    ('d7b50000-0000-5000-8000-000000000004'::uuid, '03c8f2fe-9048-5e23-8d11-a51ccfa21be0'::uuid, 'Yuvarlak bir ağ yapılırken en son ne örülür?', 1, 2, 5, 'Sırasıyla köprü, dış çerçeve ve tekerlek teli gibi iplikler kurulur; en sonunda merkezden dışa dönen yapışkan sarmal örülür.',
     'Dallar arasına kurulan ilk köprü', 'Ağı çevreleyen sağlam dış çerçeve', 'Tekerlek teli gibi uzanan iplikler', 'Ortadan dışa dönen yapışkan halka', 'D', 3),
    ('d7b50000-0000-5000-8000-000000000005'::uuid, '03c8f2fe-9048-5e23-8d11-a51ccfa21be0'::uuid, 'Bazı örümceklerin eskiyen ağlarını yemesi ne işe yarar?', 2, 4, 5, 'Eski ağı yiyen örümcek, ipeğin yapımındaki maddeleri yeniden kullanır ve yeni ağ için kaynak toplar.',
     'Avının izini ortadan kaldırır', 'Yeni ağ için malzemeyi geri kazanır', 'Yırtılan ağı daha da yapışkan yapar', 'Ağın yerini başkalarından saklar', 'B', 4),
    ('d7b50000-0000-5000-8000-000000000006'::uuid, '03c8f2fe-9048-5e23-8d11-a51ccfa21be0'::uuid, 'Ağ kurmayan örümceklerle ilgili hangisi doğrudur?', 2, 4, 5, 'Kurt ve sıçrayan örümcekler ağ kurmaz ama ipek üretir; ipeği yumurtalarını korumak, sığınak ya da güvenlik ipi için kullanır.',
     'Hiç ipek üretmezler, yalnızca koşarlar', 'Onlar da ipeği başka işlerde kullanır', 'Avlarını yalnızca kokuyla bulurlar', 'Yumurtalarını her zaman toprağa gömerler', 'B', 5),
    ('d7b50000-0000-5000-8000-000000000007'::uuid, '03c8f2fe-9048-5e23-8d11-a51ccfa21be0'::uuid, 'Yavruların rüzgârla uzaklara taşınmasının yararı nedir?', 2, 4, 5, 'Uzaklara taşınan yavrular kardeşleriyle aynı yerde kalıp yiyecek için yarışmak zorunda kalmaz.',
     'Kış gelmeden sıcak yerlere varmaları', 'Yeni ağ kurmayı orada öğrenmeleri', 'Besin için aynı yerde çekişmemeleri', 'Annelerini daha kolay bulabilmeleri', 'C', 6),
    ('d7b50000-0000-5000-8000-000000000008'::uuid, '03c8f2fe-9048-5e23-8d11-a51ccfa21be0'::uuid, 'Yazarın son paragraftaki amacı nedir?', 3, 5, 5, 'Yazar örümceklerin doğadaki görevini hatırlatır ve okura ağı bozmadan yakından incelemesini önerir.',
     'Örümceklerin tehlikeli olduğunu anlatmak', 'Ağların nasıl temizleneceğini göstermek', 'Sineklerin zararlarını sıralamak', 'Örümceklere saygıyla bakmayı öğütlemek', 'D', 7),
    ('d7b50000-0000-5000-8000-000000000009'::uuid, '09b6fc56-c553-51f5-846f-51a9e81a85b9'::uuid, 'Kerem takımda hangi görevdeydi?', 1, 1, 4, 'İlk paragrafa göre takımın kalecisi Ozan''dı; Kerem ise yedek kaleciydi.',
     'Takım kaptanı', 'Kalecinin yedeği', 'Kaleci antrenörü', 'Savunma oyuncusu', 'B', 0),
    ('d7b50000-0000-5000-8000-000000000010'::uuid, '09b6fc56-c553-51f5-846f-51a9e81a85b9'::uuid, 'Levent Bey''in kızmak yerine Kerem''e maçta ne gördüğünü sorması neyi amaçlıyordu?', 2, 4, 4, 'Kerem maçı doğru dürüst izlememişti; soru aklına takılır ve bir sonraki maçta oyunu gerçekten izlemeye karar verir.',
     'Kerem''in tribündeki arkadaşlarını tanımasını', 'Kerem''in takımdan ayrılmaya karar vermesini', 'Kerem''in Ozan''la hemen yer değiştirmesini', 'Kerem''in oyunu dikkatle izlemeye yönelmesini', 'D', 1),
    ('d7b50000-0000-5000-8000-000000000011'::uuid, '09b6fc56-c553-51f5-846f-51a9e81a85b9'::uuid, 'Kerem rakibin köşe vuruşlarıyla ilgili neyi fark etti?', 1, 2, 4, 'Üçüncü paragrafa göre köşe vuruşlarını hep aynı oyuncu kullanıyor, top çoğunlukla ön direğe gönderiliyordu.',
     'Topların çoğunun arka direğe geldiğini', 'Vuruşları hep farklı oyuncunun kullandığını', 'Topların çoğunun ön direğe geldiğini', 'Topların çoğunun yerden kesildiğini', 'C', 2),
    ('d7b50000-0000-5000-8000-000000000012'::uuid, '09b6fc56-c553-51f5-846f-51a9e81a85b9'::uuid, 'Kerem''in maçtan sonra bir sonraki maçı beklemesi neyi gösterir?', 2, 4, 4, 'Notları sayesinde iki köşe vuruşu tehlike yaratmamıştır; Kerem kulübede de katkı sunabildiğini görür ve maçları beklemeye başlar.',
     'İlk on bire gireceğinden emin olduğunu', 'Ozan''ın sakatlanacağını tahmin ettiğini', 'Kenarda da işe yarayabildiğini gördüğünü', 'Defterini antrenöre vermek hiç istemediğini', 'C', 3),
    ('d7b50000-0000-5000-8000-000000000013'::uuid, '09b6fc56-c553-51f5-846f-51a9e81a85b9'::uuid, 'Ozan, Kerem''e kalecilik hakkında ne söyledi?', 1, 2, 4, 'Ozan, kalede durmanın bazen çok yalnız hissettirdiğini, kenarda onu anlayan birinin olmasının iyi geldiğini söyler.',
     'Kalecinin bazen kendini yalnız hissettiğini', 'Kalede durmanın takımdaki en kolay görev olduğunu', 'Yerden gelen sert topları hiç sevmediğini', 'Yakında takımdan ayrılacağını düşündüğünü', 'A', 4),
    ('d7b50000-0000-5000-8000-000000000014'::uuid, '09b6fc56-c553-51f5-846f-51a9e81a85b9'::uuid, 'Levent Bey''in iyi bir takımın on bir kişiden ibaret olmadığını söylemesi Kerem''i nasıl etkiledi?', 2, 4, 4, 'Kerem bu sözü duyunca kendini kenarda unutulmuş biri değil, takımın gözlerinden biri gibi hisseder.',
     'Sahaya girmek için sabırsızlandırdı', 'Defter tutmayı bırakmaya karar verdirdi', 'Kaptan olmak istemesine yol açtı', 'Kenarda da değerli olduğunu hissettirdi', 'D', 5),
    ('d7b50000-0000-5000-8000-000000000015'::uuid, '09b6fc56-c553-51f5-846f-51a9e81a85b9'::uuid, 'Kerem ilk yarıda gol yedikten sonra kendini nasıl toparladı?', 1, 2, 4, 'Ozan kulübeden sakin olmasını işaret eder; Kerem derin nefes alıp defterindeki notları düşünür.',
     'Antrenörden oyundan çıkmayı istedi', 'Arkadaşından güç alıp planını hatırladı', 'Tribündeki arkadaşlarına el salladı', 'Eldivenlerini değiştirip yeniden ısındı', 'B', 6),
    ('d7b50000-0000-5000-8000-000000000016'::uuid, '09b6fc56-c553-51f5-846f-51a9e81a85b9'::uuid, 'Metnin sonunda Kerem takımdaki yerini nasıl görüyor?', 3, 5, 4, 'Kerem yine kulübededir ama hayal kırıklığı duymaz; takımın parçası olmanın yalnız sahadaki dakikalarla ölçülmediğini bilir.',
     'Sahada olmasa da takıma katkı sunduğunu', 'Kulübede olmanın bir haksızlık olduğunu', 'Ozan''ın yerini kesinlikle alacağını', 'Kaleci olmaktan vazgeçmesi gerektiğini', 'A', 7),
    ('d7b50000-0000-5000-8000-000000000017'::uuid, '0b3398e4-8456-52eb-87cb-386d8a5ecabe'::uuid, 'Metne göre yarasaların kanatları nasıl yapılmıştır?', 1, 1, 5, 'İlk paragrafa göre kanatlar, uzun parmak kemiklerinin arasına gerilmiş ince ve esnek bir deriden oluşur.',
     'El kemikleri arasına gerilmiş deriden', 'Kuşlarınki gibi uzun ve sık tüylerden', 'Kalın ve sert kemik plakalardan', 'Böceklerinki gibi sert kabuklardan', 'A', 0),
    ('d7b50000-0000-5000-8000-000000000018'::uuid, '0b3398e4-8456-52eb-87cb-386d8a5ecabe'::uuid, 'Böcekle beslenen yarasalar karanlıkta yollarını nasıl bulur?', 1, 2, 5, 'Bu yarasalar tiz sesler çıkarır; sesler bir nesneye çarpıp geri yansır ve yarasa bu yankıyı dinler.',
     'Güçlü koku alma duyularına güvenerek', 'Sokak lambalarının ışığını izleyerek', 'Keskin gözleriyle karanlığı seçerek', 'Kendi seslerinin dönüşünü dinleyerek', 'D', 1),
    ('d7b50000-0000-5000-8000-000000000019'::uuid, '0b3398e4-8456-52eb-87cb-386d8a5ecabe'::uuid, 'Yarasaların tiz sesleri neden uzun süre kaydedilemedi?', 2, 4, 5, 'Sesler insan kulağının duyamayacağı kadar incedir; ancak yirminci yüzyılda özel aygıtlarla kaydedilebildi.',
     'Yarasalar yalnız mağarada ses çıkarıyordu', 'Bu sesleri algılayan aygıtlar henüz yoktu', 'Sesler yalnızca kış aylarında çıkıyordu', 'Yarasalara yaklaşmak yasaklanmıştı', 'B', 2),
    ('d7b50000-0000-5000-8000-000000000020'::uuid, '0b3398e4-8456-52eb-87cb-386d8a5ecabe'::uuid, 'Yankının geri dönme süresi yarasaya neyi söyler?', 1, 2, 5, 'Üçüncü paragrafa göre yankının ne kadar sürede döndüğü, nesnenin ne kadar uzakta olduğunu gösterir.',
     'Nesnenin hangi renkte göründüğünü', 'Avın ne kadar lezzetli olduğunu', 'Engelin kendisine olan mesafesini', 'Havanın ne kadar soğuk olduğunu', 'C', 3),
    ('d7b50000-0000-5000-8000-000000000021'::uuid, '0b3398e4-8456-52eb-87cb-386d8a5ecabe'::uuid, 'Metin "yarasalar kördür" sözünü hangi bilgiyle çürütür?', 2, 4, 5, 'Yarasaların gözleri vardır ve görebilirler; yalnızca gözlerin yetmediği karanlıkta birçoğu kulaklarından yardım alır.',
     'Tümünün yankıyla yön bulabildiği', 'Gündüzleri dışarıda hiç uçmadıkları', 'Kulaklarının çok keskin olduğu', 'Görme yetilerinin de bulunduğu', 'D', 4),
    ('d7b50000-0000-5000-8000-000000000022'::uuid, '0b3398e4-8456-52eb-87cb-386d8a5ecabe'::uuid, 'Nektarla beslenen yarasaların bitkilere yararı nedir?', 2, 4, 5, 'Çiçekten çiçeğe giderken polenleri taşır ve bitkilerin tozlaşmasını sağlarlar.',
     'Çiçek tozunu bir çiçekten ötekine götürürler', 'Bitkilerin zararlı böceklerini yerler', 'Meyvelerin daha çabuk olgunlaşmasını sağlarlar', 'Çiçeklerin yapraklarını kemirip budarlar', 'A', 5),
    ('d7b50000-0000-5000-8000-000000000023'::uuid, '0b3398e4-8456-52eb-87cb-386d8a5ecabe'::uuid, 'Yaşadıkları yerler zarar görünce yarasaların sayısı neden geç artar?', 2, 4, 5, 'Birçok türde anne yılda yalnız bir yavru doğurur; az yavru yapıldığı için sayının yeniden artması uzun sürer.',
     'Yavrular uçmayı ancak yıllar içinde öğrendiği için', 'Anneler yılda genellikle tek yavru doğurduğu için', 'Anneler sütü yalnızca yazın verebildiği için', 'Yarasalar kış uykusunda çok uzun kaldığı için', 'B', 6),
    ('d7b50000-0000-5000-8000-000000000024'::uuid, '0b3398e4-8456-52eb-87cb-386d8a5ecabe'::uuid, 'Yazar yarasaları neden gecenin çalışkan yardımcıları olarak görür?', 3, 5, 5, 'Metin boyunca anlatıldığı gibi böcek yer, çiçek tozunu taşır, tohum yayarlar; bu yüzden yazar onları gecenin yardımcıları sayar.',
     'Geceleri evlerin çatılarını onardıkları için', 'İnsanlara karanlıkta yol gösterdikleri için', 'Geceleri doğaya pek çok yararı dokunduğu için', 'Mağaralarda gün boyu sessizce yaşadıkları için', 'C', 7),
    ('d7b50000-0000-5000-8000-000000000025'::uuid, '0b3878e5-7449-5aad-8dd9-5330ffa80c3c'::uuid, 'Kerem kahvaltıyı hazırlayacağına kime söz vermişti?', 1, 1, 1, 'İlk paragrafa göre Kerem bir hafta önce annesine kahvaltıyı hazırlayacağına söz vermişti.',
     'Babasına', 'Annesine', 'Anneannesine', 'Kardeşine', 'B', 0),
    ('d7b50000-0000-5000-8000-000000000026'::uuid, '0b3878e5-7449-5aad-8dd9-5330ffa80c3c'::uuid, 'Kerem menemeni neye bakarak yaptı?', 1, 1, 1, 'Kerem, telefonuna not ettiği anneannesinin tarifini okuyarak menemeni hazırladı.',
     'Annesinin yemek defterine', 'Eski bir yemek kitabına', 'Kardeşinin önerisine', 'Büyükannesinin tarifine', 'D', 1),
    ('d7b50000-0000-5000-8000-000000000027'::uuid, '0b3878e5-7449-5aad-8dd9-5330ffa80c3c'::uuid, 'Bıçak kaydıktan sonra Kerem''in daha yavaş doğraması neyi gösterir?', 2, 4, 1, 'Bıçak kayınca eli kesilmez ama Kerem bundan sonra yavaş doğrar; yaşadığından ders çıkarmıştır.',
     'Başına gelenden ders çıkardığını', 'Domates doğramayı hiç sevmediğini', 'Bıçağın körleştiğini düşündüğünü', 'Kahvaltıya geç kalmak istediğini', 'A', 2),
    ('d7b50000-0000-5000-8000-000000000028'::uuid, '0b3878e5-7449-5aad-8dd9-5330ffa80c3c'::uuid, 'Kerem yumurtaları ne zaman kırdı?', 1, 2, 1, 'Dördüncü paragrafa göre domatesler suyunu çekince yumurtaları kırdı.',
     'Biberleri doğramadan önce', 'Tereyağı tavada erimeden önce', 'Domateslerin suyu azalınca', 'Çay demlendikten hemen sonra', 'C', 3),
    ('d7b50000-0000-5000-8000-000000000029'::uuid, '0b3878e5-7449-5aad-8dd9-5330ffa80c3c'::uuid, 'Kerem salatalıkları neden yıldız gibi dizdi?', 2, 4, 1, 'Kardeşi Defne salatalıkların yıldız gibi dizilmesini çok severdi; Defne de tabağındaki yıldızları uzun uzun seyreder.',
     'Kardeşini mutlu etmek istediği için', 'Anneannesi öyle öğrettiği için', 'Tabakta yeterince yer kalmadığı için', 'Babası bir sürpriz istediği için', 'A', 4),
    ('d7b50000-0000-5000-8000-000000000030'::uuid, '0b3878e5-7449-5aad-8dd9-5330ffa80c3c'::uuid, 'Kerem''in Defne''ye yalnızca "Sürpriz" demesinin nedeni nedir?', 2, 3, 1, 'Kerem kahvaltıyı kimseye söylemeden hazırlıyordu; aile kalkınca masayı görüp çok şaşırır.',
     'Ne pişirdiğini kendisinin de bilmemesi', 'Kardeşinin uyumaya dönmesini istemesi', 'Yemeğin yanmasından çok korkması', 'Herkesi masayla şaşırtmak istemesi', 'D', 5),
    ('d7b50000-0000-5000-8000-000000000031'::uuid, '0b3878e5-7449-5aad-8dd9-5330ffa80c3c'::uuid, 'Babası menemen için ne söyledi?', 1, 2, 1, 'Babası, menemenin biraz tuzu az ama çok lezzetli olduğunu söyler.',
     'Biberlerin biraz fazla piştiğini', 'Tuzu biraz eksik ama nefis olduğunu', 'Anneannesininkinden güzel olduğunu', 'Yumurtaların gereğinden az piştiğini', 'B', 6),
    ('d7b50000-0000-5000-8000-000000000032'::uuid, '0b3878e5-7449-5aad-8dd9-5330ffa80c3c'::uuid, 'Metnin sonunda Kerem''in duyguları için hangisi söylenebilir?', 3, 5, 1, 'Kerem kendini büyümüş gibi hisseder ve gelecek pazar ne pişireceğini düşünmeye başlar.',
     'Yemek yapmaktan çabucak bıkmıştır', 'Bulaşıkları yıkamaktan sıkılmıştır', 'Başardığı işten güven kazanmıştır', 'Babasının tuz sözüne kırılmıştır', 'C', 7),
    ('d7b50000-0000-5000-8000-000000000033'::uuid, '0d391b7f-bc9c-5f30-83c7-50b580768f4e'::uuid, 'Öğrenciler mahallede neyi araştırmak istiyordu?', 1, 1, 2, 'Öğrenciler çeşmenin ne zaman yapıldığını ve eskiden nasıl kullanıldığını öğrenmek istiyordu.',
     'Okulun kuruluşunu', 'Pazarın eski yerini', 'Dükkânların sahiplerini', 'Çeşmenin geçmişini', 'D', 0),
    ('d7b50000-0000-5000-8000-000000000034'::uuid, '0d391b7f-bc9c-5f30-83c7-50b580768f4e'::uuid, 'Öğretmen neden farklı kaynakların karşılaştırılmasını istedi?', 2, 3, 2, 'Öğretmen herkesin hatırasının aynı olmayabileceğini söyler; tek bir anlatıyı kesin bilgi saymak yerine kaynaklar karşılaştırılır.',
     'Tek kişiyle konuşmak yasak olduğu için', 'Anıların kişiden kişiye değişebileceği için', 'Çeşmenin yakında yıkılacağı düşünüldüğü için', 'Fotoğraflar daha eğlenceli olduğu için', 'B', 1),
    ('d7b50000-0000-5000-8000-000000000035'::uuid, '0d391b7f-bc9c-5f30-83c7-50b580768f4e'::uuid, 'Nihat Bey çocukluğundan neyi hatırlıyordu?', 1, 2, 2, 'Nihat Bey çocukken çeşmenin yanında bekleyen insanları ve evlere su taşındığını hatırlıyordu; yılı kesin söyleyemedi.',
     'Çeşmenin başında kurulan pazarı', 'Okul arşivindeki eski fotoğrafları', 'Çeşmenin başında sıra bekleyenleri', 'Çeşmenin yapıldığı yılı kesin olarak', 'C', 2),
    ('d7b50000-0000-5000-8000-000000000036'::uuid, '0d391b7f-bc9c-5f30-83c7-50b580768f4e'::uuid, 'Öğrenciler Nihat Bey''in anlattıklarını yazarken neden farklı işaretler kullandı?', 2, 3, 2, 'Anlatılan olayla anlatıcının kendi tahmini aynı cümlede birbirine karışmasın diye farklı işaretler kullandılar.',
     'Notları daha süslü göstermek için', 'Bakkala teşekkür etmeyi unutmamak için', 'Olayı ve tahmini ayrı tutmak için', 'Bütün yılları sırayla dizebilmek için', 'C', 3),
    ('d7b50000-0000-5000-8000-000000000037'::uuid, '0d391b7f-bc9c-5f30-83c7-50b580768f4e'::uuid, 'Ayşe Hanım''a göre çeşmenin çevresinde ne kuruluyordu?', 1, 2, 2, 'Üçüncü paragrafa göre Ayşe Hanım çeşmenin çevresinde küçük bir pazar kurulduğunu anlattı.',
     'Bir satış yeri', 'Bir çay bahçesi', 'Bir oyun alanı', 'Bir su deposu', 'A', 4),
    ('d7b50000-0000-5000-8000-000000000038'::uuid, '0d391b7f-bc9c-5f30-83c7-50b580768f4e'::uuid, 'Öğretmen iki farklı anlatı hakkında ne düşündü?', 2, 4, 2, 'Öğretmene göre aynı yer farklı zamanlarda farklı amaçlarla kullanılmış olabilir: bir dönem su noktası, başka bir dönem buluşma yeri.',
     'Nihat Bey''in anlattıklarının uydurma olduğunu', 'İki anlatıdan birinin mutlaka çıkarılması gerektiğini', 'Görüşmelerin baştan yapılması gerektiğini', 'İkisinin farklı zamanlarda geçerli olabileceğini', 'D', 5),
    ('d7b50000-0000-5000-8000-000000000039'::uuid, '0d391b7f-bc9c-5f30-83c7-50b580768f4e'::uuid, 'Okul arşivindeki fotoğraflardan birinin arkasında ne vardı?', 1, 2, 2, 'Son paragrafa göre fotoğraflardan birinin arkasında bir yıl yazıyordu.',
     'Not edilmiş yıl', 'Fotoğrafçının adı', 'Dükkânın adresi', 'Çeşmenin çizimi', 'A', 6),
    ('d7b50000-0000-5000-8000-000000000040'::uuid, '0d391b7f-bc9c-5f30-83c7-50b580768f4e'::uuid, 'Fotoğraflarla ilgili hangi yaklaşım metne uygundur?', 3, 3, 2, 'Tabela, yol ve binalar ipucu olabilir ama tek başına kesin kanıt sayılmaz; iki fotoğrafı doğrudan aynı döneme saymak da doğru olmaz.',
     'Tarihi olan fotoğrafı ötekiyle aynı yıla koymak', 'İpuçlarını kesin kanıt saymadan incelemek', 'Tarihsiz fotoğrafları çalışmadan çıkarmak', 'Yalnızca dükkân tabelasına bakıp karar vermek', 'B', 7),
    ('d7b50000-0000-5000-8000-000000000041'::uuid, '10df399a-4f9c-557c-8e0d-1aa899f0fe93'::uuid, 'Baykuş avına fark edilmeden nasıl yaklaşabilir?', 1, 1, 2, 'İlk paragrafa göre baykuş uçarken neredeyse hiç ses çıkarmadığı için avına çok yaklaşana kadar fark edilmez.',
     'Gece karanlığında hiç görünmeyerek', 'Avının durmasını bekleyerek', 'Kanat sesini duyurmadan uçarak', 'Ağaçların arasına saklanarak', 'C', 0),
    ('d7b50000-0000-5000-8000-000000000042'::uuid, '10df399a-4f9c-557c-8e0d-1aa899f0fe93'::uuid, 'Kanadın ön kenarındaki tarak dişine benzeyen çıkıntılar ne işe yarar?', 1, 2, 2, 'İkinci paragrafa göre bu çıkıntılar havayı parçalara ayırarak sesi azaltır.',
     'Kanadı daha hızlı çırpmasını sağlar', 'Tüylerin yağmurda ıslanmasını önler', 'Avını kavramasına yardım eder', 'Havayı bölerek gürültüyü azaltır', 'D', 1),
    ('d7b50000-0000-5000-8000-000000000043'::uuid, '10df399a-4f9c-557c-8e0d-1aa899f0fe93'::uuid, 'Baykuşun kanatlarındaki üç yapı için hangisi söylenebilir?', 2, 4, 2, 'Tarak dişli kenar, kadife yüzey ve saçaklı arka kenar birlikte çalışınca baykuş sessizce süzülür.',
     'Her biri tek başına sesi yok eder', 'Ancak birlikte sessizlik sağlarlar', 'Yalnızca gece uçan kuşlarda bulunur', 'Baykuşun daha hızlı uçmasını sağlar', 'B', 2),
    ('d7b50000-0000-5000-8000-000000000044'::uuid, '10df399a-4f9c-557c-8e0d-1aa899f0fe93'::uuid, 'Baykuş gözlerini çeviremediği için ne yapar?', 1, 2, 2, 'Üçüncü paragrafa göre baykuş gözlerini değil başını çevirir; omzunun üstünden arkasına bakabilir.',
     'Gözlerini kırpar', 'Gövdesini çevirir', 'Kafasını oynatır', 'Yerinden kalkar', 'C', 3),
    ('d7b50000-0000-5000-8000-000000000045'::uuid, '10df399a-4f9c-557c-8e0d-1aa899f0fe93'::uuid, 'Peçeli baykuşta kulak deliklerinin farklı yükseklikte olması ne sağlar?', 2, 4, 2, 'Ses iki kulağa çok küçük bir zaman farkıyla ulaşır; baykuş bu farktan sesin geldiği yeri tam olarak bulur.',
     'Sesin geldiği noktayı bulmayı', 'Sesleri daha yüksek duymayı', 'Karanlıkta daha iyi görmeyi', 'Kendi sesini daha güçlü çıkarmayı', 'A', 4),
    ('d7b50000-0000-5000-8000-000000000046'::uuid, '10df399a-4f9c-557c-8e0d-1aa899f0fe93'::uuid, 'Bilim insanları baykuşların geri çıkardığı topaklardan ne öğrenir?', 1, 2, 2, 'Topaklardaki küçük kemiklere bakarak baykuşun o bölgede neler yediğini öğrenirler.',
     'Baykuşun kaç yıldır orada yaşadığını', 'Topakların hangi mevsimde yapıldığını', 'Yuvadaki yavruların sayısını ve yaşını', 'O bölgede hangi hayvanları yediklerini', 'D', 5),
    ('d7b50000-0000-5000-8000-000000000047'::uuid, '10df399a-4f9c-557c-8e0d-1aa899f0fe93'::uuid, 'Yuva kutularının asılması hangi iki sonucu doğurdu?', 2, 4, 2, 'Kutulara yerleşen baykuşlar yavrularını büyüttü; böylece hem baykuşlar yuva buldu hem de tarlalardaki fareler azaldı.',
     'Ambarlar onarıldı, zehirler bitti', 'Kuşlar barındı, kemirgenler azaldı', 'Ağaçlar korundu, baykuşlar göç etti', 'Fareler çoğaldı, çiftçiler kızdı', 'B', 6),
    ('d7b50000-0000-5000-8000-000000000048'::uuid, '10df399a-4f9c-557c-8e0d-1aa899f0fe93'::uuid, 'Yazar son paragrafta baykuşla ilgili hangi duyguyu paylaşır?', 3, 5, 2, 'Yazara göre baykuşu görmek zordur ama orada olduğunu bilmek yeterince heyecan vericidir.',
     'Gözden uzak bir canlıyı sezmenin coşkusunu', 'Geceleri ötüşünden korkulması gerektiğini', 'Baykuşların yakından izlenmesi gerektiğini', 'Ötüşün çiftçileri rahatsız ettiğini', 'A', 7),
    ('d7b50000-0000-5000-8000-000000000049'::uuid, '110acb3e-0642-5fa1-84d3-795d1dab86a5'::uuid, 'Serdar Bey''in akşamları yorgun düşmesi neden şaşırtıcıydı?', 2, 4, 2, 'İlk paragrafa göre Serdar Bey gün boyunca neredeyse hiç hareket etmediği hâlde akşamları kendini çok yorgun hissediyordu.',
     'Öğle yemeğini masasında yemiş olması', 'Sabahları çok geç kalkıyor olması', 'Gün boyu hiç kıpırdamamış olması', 'Ofisinin evine çok yakın olması', 'C', 0),
    ('d7b50000-0000-5000-8000-000000000050'::uuid, '110acb3e-0642-5fa1-84d3-795d1dab86a5'::uuid, 'Doktor Serdar Bey''e haftada ne kadar hareket etmesini önerdi?', 1, 1, 2, 'Doktor haftada en az yüz elli dakika, yani iki buçuk saat orta tempoda hareket önerdi.',
     'En az bir buçuk saat', 'En az iki buçuk saat', 'Her gün iki saat', 'En az beş saat', 'B', 1),
    ('d7b50000-0000-5000-8000-000000000051'::uuid, '110acb3e-0642-5fa1-84d3-795d1dab86a5'::uuid, 'Serdar Bey doktorun önerisini nasıl uygulanabilir hâle getirdi?', 2, 3, 2, 'Bir saatlik öğle arasının yarısında yürüyerek beş iş gününde önerilen süreyi tamamladı.',
     'Sabahları işe yürüyerek gidip gelerek', 'Akşamları spor salonuna yazılarak', 'Hafta sonları uzun yürüyüşler yaparak', 'Öğle arasının yarısında yürüyerek', 'D', 2),
    ('d7b50000-0000-5000-8000-000000000052'::uuid, '110acb3e-0642-5fa1-84d3-795d1dab86a5'::uuid, 'İlk günkü yürüyüşün yarım kalmasından hangi sonuç çıkarılabilir?', 2, 4, 2, 'On dakika sonra canı sıkılır ve yürüyüşü bırakır; ertesi gün Derya Hanım''la birlikte yürümeye karar verir.',
     'Park yürüyüş için çok küçük kalmıştır', 'Yalnız yürümek ona sıkıcı gelmiştir', 'Hava o gün yürümeye uygun değildir', 'Ayakları ilk günden ağrımaya başlamıştır', 'B', 3),
    ('d7b50000-0000-5000-8000-000000000053'::uuid, '110acb3e-0642-5fa1-84d3-795d1dab86a5'::uuid, 'Grup yürüyüş hızını neye göre ayarlıyordu?', 1, 2, 2, 'Orta tempoda insan rahatça konuşabilmeli ama şarkı söylemekte zorlanmalıydı; grup bu ölçüyü kullandı.',
     'Sohbet edebilip şarkıda zorlanmalarına', 'Telefondaki adım sayacının gösterdiğine', 'Her turda ölçtükleri nabız sayısına', 'Parkı kaç dakikada dolaştıklarına', 'A', 4),
    ('d7b50000-0000-5000-8000-000000000054'::uuid, '110acb3e-0642-5fa1-84d3-795d1dab86a5'::uuid, 'Grup yağmurlu günlerde ne yaptı?', 1, 2, 2, 'Yağmurda parkta yürümek mümkün olmayınca zemin kattan sekizinci kata merdivenleri kullandılar.',
     'Ofiste masa başında gerinme yaptı', 'Yürüyüşü ertesi güne erteledi', 'Binanın basamaklarında inip çıktı', 'Şemsiyeyle parkta yürümeyi sürdürdü', 'C', 5),
    ('d7b50000-0000-5000-8000-000000000055'::uuid, '110acb3e-0642-5fa1-84d3-795d1dab86a5'::uuid, 'Doktorun kontrol ziyaretindeki uyarısı neyi gösterir?', 2, 4, 2, 'Doktor yürüyüşün tek başına her şeyi çözmediğini söyler ve saat başı kalkıp gerinmeyi de önerir.',
     'Tek bir alışkanlığın yetmeyeceğini', 'Yürüyüşün bırakılması gerektiğini', 'Sırt ağrısının hiç geçmeyeceğini', 'Grubun gereğinden hızlı yürüdüğünü', 'A', 6),
    ('d7b50000-0000-5000-8000-000000000056'::uuid, '110acb3e-0642-5fa1-84d3-795d1dab86a5'::uuid, 'Metnin sonunda Serdar Bey''in yürüyüşe bakışı nasıl değişmiştir?', 3, 5, 2, 'Serdar Bey öğle yürüyüşlerini artık bir görev gibi değil, günün en keyifli yarım saati olarak görür.',
     'Yöneticisi katıldığı için gergin olmuştur', 'Grup büyüdüğü için yalnız yürümeye başlamıştır', 'Sağlığı düzeldiği için yürümeyi bırakmıştır', 'Zorunluluk olmaktan çıkıp keyfe dönüşmüştür', 'D', 7),
    ('d7b50000-0000-5000-8000-000000000057'::uuid, '19b113c5-3d19-5126-8ecc-f80a51b46e44'::uuid, 'Ozan''ın direksiyon derslerini kolay sanmasının nedeni nedir?', 2, 4, 2, 'Teori sınavını ilk denemede geçmek ona güven verir; direksiyon derslerinin de kolay geçeceğini düşünür.',
     'Babasının ona önceden araba öğretmesi', 'Eğitmeninin çok deneyimli olması', 'Kursun arabasının otomatik vitesli olması', 'Teori sınavını hemen geçmiş olması', 'D', 0),
    ('d7b50000-0000-5000-8000-000000000058'::uuid, '19b113c5-3d19-5126-8ecc-f80a51b46e44'::uuid, 'Nuran Hanım''a göre her yolculuk hangi adımlarla başlar?', 1, 1, 2, 'İkinci paragrafa göre önce koltuk ayarlanır, sonra aynalar, ardından emniyet kemeri takılır.',
     'Motor, far ve sinyal kontrolüyle', 'Lastik, yağ ve yakıt kontrolüyle', 'Koltuk, ayna ve kemer ayarlarıyla', 'Kemer, korna ve silecek denemesiyle', 'C', 1),
    ('d7b50000-0000-5000-8000-000000000059'::uuid, '19b113c5-3d19-5126-8ecc-f80a51b46e44'::uuid, 'Ozan''ın ilk denemelerde motoru durdurmasının nedeni neydi?', 1, 2, 2, 'Pedalı yavaşça bırakması gerekirken hızlı bırakınca araba sarsıldı ve motor stop etti.',
     'Debriyajı çok çabuk bırakması', 'Gaz pedalına hiç basmamış olması', 'Vitesi yanlış konuma takması', 'Direksiyonu sert çevirmesi', 'A', 2),
    ('d7b50000-0000-5000-8000-000000000060'::uuid, '19b113c5-3d19-5126-8ecc-f80a51b46e44'::uuid, 'Trafiğe çıktıklarında Nuran Hanım Ozan''a ne hatırlattı?', 1, 2, 2, 'Omuzlarını gevşetmesini ve yalnızca önüne değil, aynalara da düzenli göz atmasını hatırlattı.',
     'Hep sağ şeritte ve yavaş gitmesini', 'Kornayı sık sık kullanmasını', 'Direksiyonu daha sıkı kavramasını', 'Yan ve arka görüşü de izlemesini', 'D', 3),
    ('d7b50000-0000-5000-8000-000000000061'::uuid, '19b113c5-3d19-5126-8ecc-f80a51b46e44'::uuid, 'Nuran Hanım''ın park etmeyi küçük adımlara bölmesi neden işe yaradı?', 2, 4, 2, 'Ozan her adımı ayrı ayrı çalıştı ve bir hafta sonra arabayı kaldırıma çarpmadan park etmeyi başardı.',
     'Ozan''ın park sınavından muaf tutulması için', 'Zor bir işi adım adım kolaylaştırdığı için', 'Park yerlerinin o hafta boş olduğu için', 'Kaldırımın o sokakta çok alçak olduğu için', 'B', 4),
    ('d7b50000-0000-5000-8000-000000000062'::uuid, '19b113c5-3d19-5126-8ecc-f80a51b46e44'::uuid, 'Nuran Hanım, korna çalınmasına rağmen hızlanmayan Ozan''ı neden tebrik etti?', 2, 5, 2, 'Yağmurda yol kaygandır ve fren geç tutar; Ozan arkadaki sürücünün baskısına rağmen güvenli hızda kaldı.',
     'Arkadaki sürücüyle tartışmadığı için', 'Kaygan yolda güvenliği öne aldığı için', 'Dersi zamanından önce bitirdiği için', 'Camların buğusunu kendi başına sildiği için', 'B', 5),
    ('d7b50000-0000-5000-8000-000000000063'::uuid, '19b113c5-3d19-5126-8ecc-f80a51b46e44'::uuid, 'Gece dersinde koyu giysili yayayı son anda görmesi Ozan''a ne öğretti?', 2, 4, 2, 'Yayayı son anda fark eden Ozan, gece sürüşünün neden daha yavaş yapılması gerektiğini anladı.',
     'Uzun farların hep açık tutulmasını', 'Yaya geçitlerinden kaçınmak gerektiğini', 'Karanlıkta daha ağır sürmenin gereğini', 'Farlara doğrudan bakmanın yararını', 'C', 6),
    ('d7b50000-0000-5000-8000-000000000064'::uuid, '19b113c5-3d19-5126-8ecc-f80a51b46e44'::uuid, 'Metnin sonunda Ozan''ın iyi sürücü anlayışı nasıl değişmiştir?', 3, 5, 2, 'İlk derste acele etmek isteyen Ozan, artık iyi sürücünün hızlı değil dikkatli olan sürücü olduğunu bilir.',
     'Hızdan çok dikkati önemser hâle gelmiştir', 'Teoriyi pratikten önemli bulmaktadır', 'Sınavı geçmeyi her şeyden üstün tutmaktadır', 'Eğitmensiz sürmeyi daha kolay bulmaktadır', 'A', 7),
    ('d7b50000-0000-5000-8000-000000000065'::uuid, '1ac0f79b-9fb7-5948-8f6f-5b7ece4c746d'::uuid, 'Emre maratona nasıl katılmaya karar verdi?', 1, 1, 3, 'Emre o sabah uyumayı tercih ederdi, ama oda arkadaşı Kerem çoktan iki kişilik kayıt yaptırmıştı.',
     'Kulüp ona doğrudan görev verince', 'Arkadaşı onun adına da yazılınca', 'Koşucu olarak kayıt yaptırınca', 'Organizasyondan iş teklifi alınca', 'B', 0),
    ('d7b50000-0000-5000-8000-000000000066'::uuid, '1ac0f79b-9fb7-5948-8f6f-5b7ece4c746d'::uuid, 'Bardakların yarıdan biraz fazla doldurulması neden istendi?', 2, 4, 3, 'Ağzına kadar dolu bardak koşarken dökülüyor, koşucunun üstüne başına sıçrıyordu.',
     'Koşucu içerken dökülüp sıçramasın diye', 'Su yarışın sonuna kadar yetsin diye', 'Bardaklar masada kolayca devrilmesin diye', 'Koşucular çok su içip yorulmasın diye', 'A', 1),
    ('d7b50000-0000-5000-8000-000000000067'::uuid, '1ac0f79b-9fb7-5948-8f6f-5b7ece4c746d'::uuid, 'Masalar arasında birkaç metre boşluk bırakılmasının amacı neydi?', 2, 4, 3, 'Seda boşluğu, koşucular hangi içeceği alacaklarına önceden karar verebilsin diye istedi.',
     'Koşucuların seçimini önceden yapması', 'Gönüllülerin masalar arasında dinlenmesi', 'Kamyonetin masalara kadar yanaşabilmesi', 'Bidonların yere düzgün dizilebilmesi', 'A', 2),
    ('d7b50000-0000-5000-8000-000000000068'::uuid, '1ac0f79b-9fb7-5948-8f6f-5b7ece4c746d'::uuid, 'Öndeki koşucular istasyondan nasıl geçti?', 1, 2, 3, 'Önde giden grup neredeyse hiç yavaşlamadan geldi; bir koşucu bardağı kapıp iki saniyede geçti.',
     'Masada durup dinlenerek', 'Gönüllülerle sohbet ederek', 'Hızlarını hemen hiç kesmeden', 'Bardağı yere bırakıp durarak', 'C', 3),
    ('d7b50000-0000-5000-8000-000000000069'::uuid, '1ac0f79b-9fb7-5948-8f6f-5b7ece4c746d'::uuid, 'Kerem bardak doldurma işini nasıl hızlandırdı?', 1, 2, 3, 'Kerem bidonun musluğunu açık bırakıp bardakları bir sıra hâlinde altından geçirdi; Emre de bu yöntemi denedi.',
     'Bardakları bidona daldırıp çabucak doldurarak', 'Musluk açıkken bardakları sırayla altından geçirerek', 'Koşuculardan kendi bardaklarını getirmelerini isteyerek', 'Bütün bardakları önceden doldurup üst üste koyarak', 'B', 4),
    ('d7b50000-0000-5000-8000-000000000070'::uuid, '1ac0f79b-9fb7-5948-8f6f-5b7ece4c746d'::uuid, 'Başı dönen koşucu olayı Emre''ye neyi kavrattı?', 2, 4, 3, 'Seda sağlık ekibine hemen haber verdi; Emre eğitimde bu konunun neden bu kadar ayrıntılı anlatıldığını o an anladı.',
     'Koşucuların hızlı içmesi gerektiğini', 'İstasyonun yanlış yere kurulduğunu', 'Eğitimdeki sağlık bilgilerinin önemini', 'Seda''nın telsizi gereksiz kullandığını', 'C', 5),
    ('d7b50000-0000-5000-8000-000000000071'::uuid, '1ac0f79b-9fb7-5948-8f6f-5b7ece4c746d'::uuid, 'Seda''nın son koşuculara da özen gösterilmesini istemesinin nedeni nedir?', 2, 5, 3, 'Seda''ya göre onlar yolda en uzun süre kalan kişilerdir; bir bardak suya ve iyi bir söze en çok onların ihtiyacı olabilir.',
     'Su o saatlerde çok bol olduğu için', 'Onlar yarışı kazanmaya yakın olduğu için', 'Organizasyon bunu zorunlu tuttuğu için', 'Parkurda en çok onlar kaldığı için', 'D', 6),
    ('d7b50000-0000-5000-8000-000000000072'::uuid, '1ac0f79b-9fb7-5948-8f6f-5b7ece4c746d'::uuid, 'Metnin sonunda Emre maraton hakkında hangi sonuca varır?', 3, 5, 3, 'Emre bir yarışın yalnız koşanlardan oluşmadığını, onu mümkün kılan sessiz bir ekibin her kilometrede beklediğini anlar.',
     'Koşmanın gönüllülükten daha kolay olduğuna', 'Su istasyonlarının yarışta gereksiz olduğuna', 'Gelecek yıl kesinlikle gönüllü olmayacağına', 'Yarışı arka plandaki emekçilerin taşıdığına', 'D', 7),
    ('d7b50000-0000-5000-8000-000000000073'::uuid, '1d3793ac-fa75-5a06-8b55-9f31470f6bbc'::uuid, 'Şefin Deniz''i hiç konuşmadan işe koşması ona ne anlattı?', 2, 4, 5, 'Şef ilk sabah eline bir bıçak ve bir kasa soğan tutuşturur; Deniz burada kendini sözlerle değil işle tanıtması gerektiğini anlar.',
     'Kendini sözle değil işle tanıtacağını', 'Mutfakta yalnızca soğan doğrayacağını', 'Şefin kendisini hiç beğenmediğini', 'Stajın birkaç gün içinde biteceğini', 'A', 0),
    ('d7b50000-0000-5000-8000-000000000074'::uuid, '1d3793ac-fa75-5a06-8b55-9f31470f6bbc'::uuid, '"Akşamın sakinliği, sabahın titizliğinde saklıdır" sözü ne anlatır?', 2, 4, 5, 'Siparişler yağmaya başladığında kimsenin soğan soymaya vakti olmaz; hazırlığı eksik bir tezgâh bütün mutfağı tıkar.',
     'Akşam servisinde sessiz çalışmak gerekir', 'Sabahları mutfakta kimse konuşmamalıdır', 'Yoğun akşamlarda hazırlık yeniden yapılır', 'Rahat servis, önceki hazırlığa bağlıdır', 'D', 1),
    ('d7b50000-0000-5000-8000-000000000075'::uuid, '1d3793ac-fa75-5a06-8b55-9f31470f6bbc'::uuid, 'Deniz bulaşıkhanenin önemini neden ızgara kadar büyük buldu?', 2, 4, 5, 'Temiz tabak gelmezse ızgaradaki en iyi balık da hiçbir işe yaramaz; bu yüzden bulaşıkhane en az ızgara kadar önemlidir.',
     'Temiz tabak olmadan iyi yemeğin de sunulamaması', 'Hüseyin Amca''nın mutfağın en deneyimlisi olması', 'Bulaşıkhanenin ızgaraya çok yakın kurulmuş olması', 'Tabakların süslenmesinin orada yapılıyor olması', 'A', 2),
    ('d7b50000-0000-5000-8000-000000000076'::uuid, '1d3793ac-fa75-5a06-8b55-9f31470f6bbc'::uuid, 'Sevgi Hanım hızlanmak isteyen Deniz''e ne önerdi?', 1, 2, 5, 'Şefe göre hız, doğru hareketin binlerce kez tekrarlanmasından kendiliğinden doğacaktı; önce tutuş ve parmak duruşu düzelmeliydi.',
     'Pınar''ı izleyip onun hızına yetişmesini', 'Soğanları iri ve kaba parçalar hâlinde doğramasını', 'Önce bıçağı ve parmaklarını doğru tutmasını', 'Hazırlığı servisten hemen önce yapmasını', 'C', 3),
    ('d7b50000-0000-5000-8000-000000000077'::uuid, '1d3793ac-fa75-5a06-8b55-9f31470f6bbc'::uuid, 'Siparişlerin her istasyonda yeniden söylenmesi Deniz''in gözünde neden değer kazandı?', 2, 5, 5, 'Fındık alerjisi notu Pınar''ın tekrarında fark edilmiş, fındıklı sos tabağa konmadan durdurulmuştu; tekrar bir güvenlik ağıdır.',
     'Mutfaktaki gürültüyü epeyce azalttığı için', 'Siparişlerin daha çabuk çıkmasını sağladığı için', 'Bir alerji notunu yakalamaya yaradığı için', 'Müşterilerin bunu mutfaktan duyabildiği için', 'C', 4),
    ('d7b50000-0000-5000-8000-000000000078'::uuid, '1d3793ac-fa75-5a06-8b55-9f31470f6bbc'::uuid, 'Deniz çorba tarifini neden değiştirdi?', 1, 2, 5, 'Tarif iri levrek gerektiriyordu; kasalarda ise küçük kaya balıkları ve midye vardı. Deniz denizin o gün sunduğuyla çalıştı.',
     'Şef baharatlı yemekleri sevmediği için', 'Tezgâha başka cins balıklar geldiği için', 'Krema o sabah lokantada kalmadığı için', 'Müşteriler o gün balık çorbası istemediği için', 'B', 5),
    ('d7b50000-0000-5000-8000-000000000079'::uuid, '1d3793ac-fa75-5a06-8b55-9f31470f6bbc'::uuid, 'Kemal Usta alev alan tavaya nasıl müdahale etti?', 1, 2, 5, 'Kemal Usta telaşlanmadan tavanın kapağını kapattı ve ocağı söndürdü; yağ yangınında alevin havası kesilir.',
     'Üstüne bir kova su döktü', 'Tavayı örtüp ateşi kesti', 'Tavayı hemen dışarı taşıdı', 'Söndürücüyle alevi söndürdü', 'B', 6),
    ('d7b50000-0000-5000-8000-000000000080'::uuid, '1d3793ac-fa75-5a06-8b55-9f31470f6bbc'::uuid, 'Metnin sonuna göre bu staj Deniz''e asıl ne kazandırdı?', 3, 5, 5, 'Defteri tarif değil gözlemle doludur; mevsim ona yemek yapmayı değil, bir mutfağın içinde nasıl var olunacağını öğretmiştir.',
     'Yeni ve süslü tarifler yazmayı', 'Kendi lokantasını açma cesaretini', 'Okulu bırakma kararını vermeyi', 'Bir mutfak ekibinde yer almayı', 'D', 7),
    ('d7b50000-0000-5000-8000-000000000081'::uuid, '1d677e6f-3f90-50ce-8f31-d9c41adfcd6a'::uuid, 'Gülce''nin koşu programına yazılmasında en etkili düşünce hangisidir?', 2, 4, 3, 'Gülce koşmaktan kaçan biriydi; yine de yeni bir şehirde yeni bir şey denemek istediği için adını yazdı.',
     'Farklı bir şehirde kendini sınamak', 'Lisede koşuda çok başarılı olmak', 'Halk koşusunda derece almak istemek', 'Beden eğitimi notunu yükseltmek', 'A', 0),
    ('d7b50000-0000-5000-8000-000000000082'::uuid, '1d677e6f-3f90-50ce-8f31-d9c41adfcd6a'::uuid, 'Tuna''ya göre yeni başlayanların en sık yaptığı hata nedir?', 1, 2, 3, 'İkinci paragrafa göre en sık hata, her antrenmanı bir yarış gibi koşmaktır.',
     'Antrenmanlara düzensiz gelmek', 'Her antrenmanı yarışa çevirmek', 'Isınmadan hemen koşmaya başlamak', 'Pistte konuşarak dikkati dağıtmak', 'B', 1),
    ('d7b50000-0000-5000-8000-000000000083'::uuid, '1d677e6f-3f90-50ce-8f31-d9c41adfcd6a'::uuid, 'Tuna koşu temposunun doğru olup olmadığını anlamak için hangi ölçüyü verdi?', 1, 2, 3, 'Tuna, Gülce''ye yanındakiyle sohbet ederek koşmasını önerdi; konuşamıyorsa fazla hızlı gidiyordur.',
     'Nabzını her turda tek tek saymayı', 'Nefes kesilmeden söyleşebilmeyi', 'Arda''nın hızına ayak uydurmayı', 'Pisti hep aynı sürede dönmeyi', 'B', 2),
    ('d7b50000-0000-5000-8000-000000000084'::uuid, '1d677e6f-3f90-50ce-8f31-d9c41adfcd6a'::uuid, 'Programın önüne geçen öğrencinin sakatlanması grup için neden ders oldu?', 2, 4, 3, 'Tuna''ya göre eklemler ve bağlar yüke alışmak için zamana ihtiyaç duyar; mesafe her hafta yalnız biraz artırılmalıdır.',
     'Dizin koşuda hiç kullanılmadığını gösterdiği için', 'Fazladan koşunun hep yarar sağladığını gösterdiği için', 'Dinlenme günlerinin gereksiz olduğunu gösterdiği için', 'Bedenin yüke yavaş yavaş alıştığını gösterdiği için', 'D', 3),
    ('d7b50000-0000-5000-8000-000000000085'::uuid, '1d677e6f-3f90-50ce-8f31-d9c41adfcd6a'::uuid, 'Gülce sınav haftalarında antrenmanları neden kaçırmamaya çalıştı?', 1, 2, 3, 'Gülce koştuktan sonra çalışırken daha kolay odaklanabildiğini fark etmişti.',
     'Tuna devamsızlığa izin vermediği için', 'Yarış tam o hafta yapılacağı için', 'Koşunca derse daha iyi odaklandığı için', 'Arda''yla birlikte ders çalıştıkları için', 'C', 4),
    ('d7b50000-0000-5000-8000-000000000086'::uuid, '1d677e6f-3f90-50ce-8f31-d9c41adfcd6a'::uuid, '"Başta kazanılan birkaç saniye sonda dakikalar olarak geri ödenir" sözü ne anlatır?', 2, 4, 3, 'Başlangıçtaki coşkuyla hızlananların çoğu yarışın ortasında yorulup yürümek zorunda kalır.',
     'İlk kilometrede herkes yürümelidir', 'Yarışın sonu başından daha kolaydır', 'Erken hız sonradan pahalıya patlar', 'Saniyeleri hesaplamak çok önemlidir', 'C', 5),
    ('d7b50000-0000-5000-8000-000000000087'::uuid, '1d677e6f-3f90-50ce-8f31-d9c41adfcd6a'::uuid, 'Gülce yarıştan önceki akşam neden yeni ayakkabılarını kutusuna geri koydu?', 1, 2, 3, 'Arda, Tuna''nın uyarısını hatırlatır: yarış günü ne yeni ayakkabı ne yeni kahvaltı denenir.',
     'Ayakkabılar ayağına küçük geldiği için', 'Arda o ayakkabıları beğenmediği için', 'Yeni ayakkabılar yağmurda kayacağı için', 'Büyük günde yenilik yapılmayacağı için', 'D', 6),
    ('d7b50000-0000-5000-8000-000000000088'::uuid, '1d677e6f-3f90-50ce-8f31-d9c41adfcd6a'::uuid, 'Gülce''nin yeni dönemde gönüllü olması onun hakkında ne söyler?', 3, 5, 3, 'Gülce yeni başlayanlara eşlik eder ve bir zamanlar kendisine söylenen öğüdü tekrarlar.',
     'Öğrendiğini yenilere aktarmak istediğini', 'Yeni bir yarışa hiç hazırlanmadığını', 'Koşu kulübünden tamamen soğuduğunu', 'Antrenör olmayı uzun süredir planladığını', 'A', 7),
    ('d7b50000-0000-5000-8000-000000000089'::uuid, '1fff7d83-84e9-5d76-8ae3-1f68d69a8ae9'::uuid, 'Meteoroloji istasyonu nerede bulunuyordu?', 1, 1, 3, 'İlk paragrafa göre istasyon havaalanı yolunun kenarında, tel örgüyle çevrili geniş bir çayırdaydı.',
     'Kent merkezinde, yüksek binada', 'Şehrin dışında, geniş bir otlakta', 'Üniversite kampüsünde, bir bahçede', 'Ormanın içinde, bir tepenin üstünde', 'B', 0),
    ('d7b50000-0000-5000-8000-000000000090'::uuid, '1fff7d83-84e9-5d76-8ae3-1f68d69a8ae9'::uuid, 'Termometrelerin beyaz, panjurlu bir kulübede tutulmasının amacı nedir?', 2, 4, 3, 'Beyaz renk güneşi yansıtır, panjur havanın dolaşmasını sağlar; Kemal Bey''e göre güneşin altında ısınan aletin değil havanın sıcaklığı ölçülmelidir.',
     'Aletleri yağmurdan ve kardan korumak', 'Gece ölçümlerinin kolay okunmasını sağlamak', 'Güneşin ısıttığı aleti değil havayı ölçmek', 'Aletlerin çalınmasını ve kırılmasını önlemek', 'C', 1),
    ('d7b50000-0000-5000-8000-000000000091'::uuid, '1fff7d83-84e9-5d76-8ae3-1f68d69a8ae9'::uuid, 'Rüzgâr ölçer neden binalardan ve ağaçlardan uzağa konmuştur?', 1, 2, 3, 'Yakındaki bir duvar bile rüzgârın hızını ve yönünü değiştirebilirdi.',
     'Engeller ölçümü bozabileceği için', 'Fincanları çok ses çıkardığı için', 'Yüksek direk yıkılabileceği için', 'Ağaçlar aleti gölgede bırakacağı için', 'A', 2),
    ('d7b50000-0000-5000-8000-000000000092'::uuid, '1fff7d83-84e9-5d76-8ae3-1f68d69a8ae9'::uuid, 'Gözlemciler gökyüzünün ne kadar kapalı olduğunu nasıl belirliyordu?', 1, 2, 3, 'Kemal Bey gökyüzünü sekiz parçaya bölerek düşünmeyi öğretti; dört parça kapalıysa gök yarı yarıya kapalı sayılıyordu.',
     'Atlastaki resimlere bakarak', 'Uzaktaki su deposunu seçerek', 'Gökyüzünü sekiz bölüme ayırarak', 'Balonun kaybolma süresini ölçerek', 'C', 3),
    ('d7b50000-0000-5000-8000-000000000093'::uuid, '1fff7d83-84e9-5d76-8ae3-1f68d69a8ae9'::uuid, 'Ölçümlerin dünyanın her yerinde aynı saatlerde yapılması ne sağlar?', 2, 4, 3, 'Aynı anda yapılan ölçümler sayesinde farklı ülkelerden gelen veriler aynı haritada bir araya getirilebiliyordu.',
     'Gece nöbetlerine hiç gerek kalmamasını', 'Gözlemcilerin mesaiyi erken bitirmesini', 'Termometrelerin daha doğru okunmasını', 'Bilgilerin ortak çizelgede buluşmasını', 'D', 4),
    ('d7b50000-0000-5000-8000-000000000094'::uuid, '1fff7d83-84e9-5d76-8ae3-1f68d69a8ae9'::uuid, 'Sonda balonundaki cihaz verileri istasyona nasıl ulaştırıyordu?', 1, 2, 3, 'Cihaz yükselirken sıcaklık, nem ve basıncı ölçüp radyo sinyalleriyle istasyona gönderiyordu.',
     'Kablosuz yayınla', 'Telefon hattıyla', 'Paraşüte yazarak', 'İnince kayıtla', 'A', 5),
    ('d7b50000-0000-5000-8000-000000000095'::uuid, '1fff7d83-84e9-5d76-8ae3-1f68d69a8ae9'::uuid, 'Kemal Bey eksik günlerin tahminle doldurulmasına neden karşı çıktı?', 2, 5, 3, 'Ona göre bir grafikteki boş aralık, uydurulmuş bir sayıdan her zaman daha dürüsttü.',
     'Tahmin yapmak saatlerce süreceği için', 'Eski defterler okunamayacak durumda olduğu için', 'Grafikte eksik gün hiç görülmediği için', 'Boşluğu açık bırakmak daha dürüst olduğu için', 'D', 6),
    ('d7b50000-0000-5000-8000-000000000096'::uuid, '1fff7d83-84e9-5d76-8ae3-1f68d69a8ae9'::uuid, 'Metnin sonunda Sena hava raporunu nasıl dinler?', 3, 5, 3, 'Sena artık her sıcaklık değerinin arkasında bir kulübe, bir balon ve dikkatle tutulmuş bir defter görür.',
     'Spikerin hatalarını tek tek not ederek', 'Sayıların ardındaki emeği hatırlayarak', 'Modellerin her şeyi bildiğine inanarak', 'Kendi tahminiyle karşılaştırıp gülerek', 'B', 7),
    ('d7b50000-0000-5000-8000-000000000097'::uuid, '204eb705-b1e4-5bc5-8c24-920c352a7da6'::uuid, 'Annesi Efe''ye şemsiyeyi neden verdi?', 1, 1, 1, 'Sabah gökyüzü griydi; annesi bugün yağmur yağabileceğini söyleyip şemsiyeyi verdi.',
     'Hava yağışlı olabileceği için', 'Güneş çok yakıcı olduğu için', 'Efe şemsiyesini kaybettiği için', 'Lale''ye vermesini istediği için', 'A', 0),
    ('d7b50000-0000-5000-8000-000000000098'::uuid, '204eb705-b1e4-5bc5-8c24-920c352a7da6'::uuid, 'Yağmur ne zaman başladı?', 1, 1, 1, 'İkinci paragrafa göre yağmur Efe okuldayken başladı.',
     'Efe evdeyken', 'Derslerdeyken', 'Akşam olunca', 'Yolda yürürken', 'B', 1),
    ('d7b50000-0000-5000-8000-000000000099'::uuid, '204eb705-b1e4-5bc5-8c24-920c352a7da6'::uuid, 'Lale kapının önünde neden bekliyordu?', 2, 3, 1, 'Lale''nin şemsiyesi yoktu ve saçları ıslanmıştı; yağmurda eve gidemiyordu.',
     'Efe''yi oyuna çağırmak istediği için', 'Islanmadan eve gidemediği için', 'Annesini bekliyor olduğu için', 'Kediyi aramak istediği için', 'B', 2),
    ('d7b50000-0000-5000-8000-000000000100'::uuid, '204eb705-b1e4-5bc5-8c24-920c352a7da6'::uuid, 'Efe, Lale''yi neden birlikte gitmeye çağırdı?', 1, 2, 1, 'Lale köşedeki sarı binayı gösterdi; Efe''nin evi de aynı yoldaydı.',
     'Lale ondan yardım istemişti', 'Annesi ona öyle söylemişti', 'Lale''nin evi çok uzaktaydı', 'İki ev aynı yol üstündeydi', 'D', 3),
    ('d7b50000-0000-5000-8000-000000000101'::uuid, '204eb705-b1e4-5bc5-8c24-920c352a7da6'::uuid, 'Efe''nin ıslanan omzuna aldırmaması onun hakkında ne gösterir?', 2, 3, 1, 'Şemsiye küçük olduğu için Efe''nin omzu ıslanır; ama Lale''yle şemsiyeyi paylaşmayı önemser ve aldırmaz.',
     'Yağmurda ıslanmayı çok sevdiğini', 'Şemsiyesini beğenmediğini', 'Eve çabuk varmak istediğini', 'Arkadaşını korumayı önemsediğini', 'D', 4),
    ('d7b50000-0000-5000-8000-000000000102'::uuid, '204eb705-b1e4-5bc5-8c24-920c352a7da6'::uuid, 'Yolda Lale kime el salladı?', 1, 1, 1, 'Bir kedi arabanın altına saklanmıştı; Lale kediye el salladı.',
     'Bir kediye', 'Bir köpeğe', 'Annesine', 'Öğretmenine', 'A', 5),
    ('d7b50000-0000-5000-8000-000000000103'::uuid, '204eb705-b1e4-5bc5-8c24-920c352a7da6'::uuid, 'Annesinin gülümseyip havlu vermesi neyi gösterir?', 2, 3, 1, 'Annesi olanları dinler, gülümser ve sıcak bir havlu verir; Efe''nin davranışını beğenmiştir.',
     'Efe''ye kızdığını ama söylemediğini', 'Islak omzu hiç fark etmediğini', 'Efe''nin davranışını beğendiğini', 'Yarın şemsiye vermeyeceğini', 'C', 6),
    ('d7b50000-0000-5000-8000-000000000104'::uuid, '204eb705-b1e4-5bc5-8c24-920c352a7da6'::uuid, 'Lale''nin yaptığı resim neyi anlatmak içindir?', 3, 3, 1, 'Resimde kırmızı bir şemsiye ve altında iki çocuk vardır; Lale bu resimle Efe''ye teşekkür eder.',
     'Yağmurdan korkusunu', 'Resim yeteneğini', 'Ona olan minnetini', 'Şemsiye istediğini', 'C', 7),
    ('d7b50000-0000-5000-8000-000000000105'::uuid, '224ebfb4-3c15-56b2-8c92-1b9841b127f9'::uuid, 'Nurcan''a göre köydeki süt sorununun asıl nedeni neydi?', 1, 2, 5, 'Nurcan''a göre sorun bir talihsizlik değil, dağınık üretimin doğal sonucuydu; aileler tek başına pazarlık ve yatırım yapamıyordu.',
     'Her ailenin kendi başına üretmesi', 'Toplayıcının köy yolunu bilmemesi', 'Hayvanların yeterince süt vermemesi', 'Peynir yapımının hiç bilinmemesi', 'A', 0),
    ('d7b50000-0000-5000-8000-000000000106'::uuid, '224ebfb4-3c15-56b2-8c92-1b9841b127f9'::uuid, 'Eski birliğin dağılma nedeni yeni kooperatifin kurallarını nasıl etkiledi?', 2, 4, 5, 'Sorun hesap vermedeki belirsizlikti; bu yüzden gelir gider tablosunun panoya asılması ve belgelerin incelenebilmesi sözleşmeye yazıldı.',
     'Yaşlıların kooperatife alınmamasını sağladı', 'Hesapların herkese açık tutulmasını sağladı', 'Kararların birkaç kişiye bırakılmasını sağladı', 'Toplantıların gizli yapılmasını sağladı', 'B', 1),
    ('d7b50000-0000-5000-8000-000000000107'::uuid, '224ebfb4-3c15-56b2-8c92-1b9841b127f9'::uuid, 'Başvuru dosyası için bilgi toplamak ailelere beklenmedik hangi yararı sağladı?', 2, 4, 5, 'Aileler köyün toplam üretimini ilk kez birlikte gördü; küçük miktarlar bir araya gelince ciddi bir hacme ulaşıyordu.',
     'Yolun kışın açık kalmasını güvenceye aldı', 'Hayvan sayısını kısa sürede artırdı', 'Toplu üretimin büyüklüğünü gösterdi', 'Tankın ücretsiz verilmesini sağladı', 'C', 2),
    ('d7b50000-0000-5000-8000-000000000108'::uuid, '224ebfb4-3c15-56b2-8c92-1b9841b127f9'::uuid, 'Nurcan ölçüm sonuçlarını neden isimsiz paylaştı?', 2, 5, 5, 'Kontroller bazılarına kişisel eleştiri gibi gelmişti; isimsiz paylaşım ölçümün kişiye değil süte yapıldığını gösterdi.',
     'Hiç kimseyi herkesin önünde mahcup etmemek için', 'Ortakların sonuçlarla ilgilenmediğini düşündüğü için', 'Ölçümlerin güvenilir olmadığından şüphelendiği için', 'Yasal olarak sonuç açıklamak yasak olduğu için', 'A', 3),
    ('d7b50000-0000-5000-8000-000000000109'::uuid, '224ebfb4-3c15-56b2-8c92-1b9841b127f9'::uuid, 'Kadınların çalışma grubunda dile getirdiği sorun neydi?', 1, 2, 5, 'Teslimat saati sabah işleriyle çakışıyor, süt bu yüzden soğumaya fırsat bulmadan getiriliyordu; saat yarım saat kaydırıldı.',
     'Sağım kaplarının sayısının yetmemesi', 'Teslimin sabah işlerine denk gelmesi', 'Toplantıların akşam çok geç bitmesi', 'Süthaneye giden yolun çamurlu olması', 'B', 4),
    ('d7b50000-0000-5000-8000-000000000110'::uuid, '224ebfb4-3c15-56b2-8c92-1b9841b127f9'::uuid, 'Peynir üreticisiyle yapılan anlaşmanın yeniliği neydi?', 1, 2, 5, 'Fiyat artık yalnızca miktara değil, yağ ve protein oranı gibi kaliteye de bağlıydı.',
     'Sütün toplayıcı yerine kamyonla alınması', 'Fiyatın ilk teklifin iki katı olması', 'Peynirin köyde üretilmeye başlanması', 'Fiyatın sütün niteliğine de bağlanması', 'D', 5),
    ('d7b50000-0000-5000-8000-000000000111'::uuid, '224ebfb4-3c15-56b2-8c92-1b9841b127f9'::uuid, 'Kayıtlardaki hatanın bu kez kavgaya dönüşmemesinin nedeni nedir?', 2, 4, 5, 'Kayıtlar herkesin incelemesine açıktı; hatayı ilgili ortak kendisi fark etti ve toplantıda açıkça düzeltildi.',
     'Hatanın tutarının çok küçük olması', 'Ortakların artık birbirine küs olmaması', 'Yönetimin hatayı gizlice düzeltmesi', 'Açık kayıtlarla erken fark edilmesi', 'D', 6),
    ('d7b50000-0000-5000-8000-000000000112'::uuid, '224ebfb4-3c15-56b2-8c92-1b9841b127f9'::uuid, 'Nurcan''a göre kooperatifin en önemli kazancı nedir?', 3, 5, 5, 'Nurcan''a göre en önemli kazanç tank ya da fiyat değil, köyde güvenin yeniden kurulmasıydı.',
     'Soğutma tankının köye kazandırılması', 'Sütün en yüksek fiyattan satılması', 'Köyde birbirine güvenin geri gelmesi', 'Gençlerin şehre göç etmesinin durması', 'C', 7),
    ('d7b50000-0000-5000-8000-000000000113'::uuid, '23d55d85-b65f-5e7a-88ba-ce0d3adb0713'::uuid, 'Görüşmede sorulan tek soru, işin hangi yönüne işaret ediyordu?', 2, 4, 4, '"Bir cümleyi kısaltmaya kıyamayan biri misin?" sorusu, altyazıda metnin sık sık kısaltılması gerektiğini sezdirir.',
     'Pek çok yabancı dil bilmenin gerektiğine', 'Ekip içinde sürekli konuşulduğuna', 'İşin yalnızca geceleri yapıldığına', 'Metni kısaltmak zorunda kalınacağına', 'D', 0),
    ('d7b50000-0000-5000-8000-000000000114'::uuid, '23d55d85-b65f-5e7a-88ba-ce0d3adb0713'::uuid, 'Cemil Bey ilk gün Aslı''dan ne istedi?', 1, 2, 4, 'Cemil Bey önüne kısa bir belgesel koydu ve önce hiçbir şey yazmadan yalnızca izlemesini istedi.',
     'Filmi yazmadan önce baştan izlemesini', 'Bütün belgeseli hemen o gün çevirmesini', 'Stüdyodaki afişleri düzenlemesini', 'Konuşmaları tek tek ezberlemesini', 'A', 1),
    ('d7b50000-0000-5000-8000-000000000115'::uuid, '23d55d85-b65f-5e7a-88ba-ce0d3adb0713'::uuid, 'Aslı''nın ilk denemesi neden işe yaramadı?', 2, 4, 4, 'Dört satırlık bloklar ekranda birkaç saniye kalıyor, Aslı bile okumaya yetişemiyordu.',
     'Çeviride çok sayıda yanlış vardı', 'Yazılar okunamayacak kadar uzundu', 'Balıkçının sözleri hiç anlaşılmıyordu', 'Yazılar ekranın üstünde çıkıyordu', 'B', 2),
    ('d7b50000-0000-5000-8000-000000000116'::uuid, '23d55d85-b65f-5e7a-88ba-ce0d3adb0713'::uuid, 'Cemil Bey''e göre hangi ögeler kısaltılsa da korunmalıdır?', 1, 2, 4, 'Dolgu sözcükler ve tekrarlar atılabilir; ama kişiliği gösteren bir deyim ya da şaka mutlaka korunmalıdır.',
     'Konuşanın kendini düzelttiği yerler', 'Tekrarlanan bütün cümle ve sözler', '"Yani", "işte" gibi dolgu sözcükler', 'Konuşanı tanıtan deyim ve şakalar', 'D', 3),
    ('d7b50000-0000-5000-8000-000000000117'::uuid, '23d55d85-b65f-5e7a-88ba-ce0d3adb0713'::uuid, 'Aslı konuşmanın başladığı anı bulmak için neden yararlandı?', 1, 2, 4, 'Beşinci paragrafa göre Aslı ses dalgasını gösteren çizgiye bakarak konuşmanın başladığı anı bulmayı öğrendi.',
     'Ses dalgası çizgisinden', 'Konuşanın dudaklarından', 'Yönetmenin notlarından', 'Kurgu kesmelerinden', 'A', 4),
    ('d7b50000-0000-5000-8000-000000000118'::uuid, '23d55d85-b65f-5e7a-88ba-ce0d3adb0713'::uuid, 'Cemil Bey''in deyim çevirisine bir şey söylemeden devam etmesi neyi gösterir?', 2, 4, 4, 'Aslı sonradan bu suskunluğun stüdyodaki en büyük övgü olduğunu öğrendi.',
     'Çeviriyi hiç okumadığını', 'Aslı''ya kırgın olduğunu', 'Çeviriyi uygun bulduğunu', 'Deyimi gereksiz bulduğunu', 'C', 5),
    ('d7b50000-0000-5000-8000-000000000119'::uuid, '23d55d85-b65f-5e7a-88ba-ce0d3adb0713'::uuid, 'Aslı kendi işini neden bir gece bekledikten sonra yeniden izliyordu?', 2, 5, 4, 'Başkasının hatasını bulmanın kendi hatasını görmekten kolay olduğunu fark eden Aslı, işine yeni bir gözle bakmak için bekliyordu.',
     'Stüdyo kuralı bekletmeyi şart koştuğu için', 'Gece çalışmak ona daha verimli geldiği için', 'Kendi yanlışını görmek daha zor olduğu için', 'Cemil Bey dosyaları sabah okumayı istediği için', 'C', 6),
    ('d7b50000-0000-5000-8000-000000000120'::uuid, '23d55d85-b65f-5e7a-88ba-ce0d3adb0713'::uuid, 'Metnin sonunda Aslı''nın tutumu için hangisi söylenebilir?', 3, 5, 4, 'Salondakiler kalkarken Aslı bir sonraki filmde neyi daha iyi yapabileceğini düşünür ve ertesi sabah stüdyoya erkenden gider.',
     'Adının görünmemesine üzülmüştür', 'Daha iyisini yapmaya odaklanmıştır', 'Stüdyodan ayrılmaya karar vermiştir', 'İzleyicilerin ilgisizliğine kırılmıştır', 'B', 7),
    ('d7b50000-0000-5000-8000-000000000121'::uuid, '26590948-2bd2-5abb-86cd-1863f06ff8bf'::uuid, 'Sevgi Hanım''ı kompost yapmaya yönelten düşünce hangisidir?', 2, 4, 3, 'Mutfak atıklarının her gün şehir dışındaki depolama alanına gitmesi ona tuhaf gelir; oysa bunlar toprağa geri dönebilecek şeylerdir.',
     'Geri kazanılacak atıkların çöpe gitmesi', 'Çöp kamyonunun apartmana hiç uğramaması', 'Bahçenin bakımsız bir çöplüğe dönmesi', 'Komşularının çöpü yanlış ayırması', 'A', 0),
    ('d7b50000-0000-5000-8000-000000000122'::uuid, '26590948-2bd2-5abb-86cd-1863f06ff8bf'::uuid, 'Yığında nemli atıklar fazla olursa ne olur?', 1, 2, 3, 'Rehbere göre yığın fazla yeşil olursa ıslak ve kokulu bir çamura dönüşür; fazla kahverengi olursa aylarca değişmez.',
     'Aylarca hiç değişmeden kalır', 'Sulanıp ağır bir koku yayar', 'Hemen kuruyup toza dönüşüverir', 'Solucanlar yığını terk eder', 'B', 1),
    ('d7b50000-0000-5000-8000-000000000123'::uuid, '26590948-2bd2-5abb-86cd-1863f06ff8bf'::uuid, 'Sevgi Hanım''ın altı aylık deneme önermesi nasıl bir tutumdur?', 2, 4, 3, 'Tartışmayı uzatmaz; şikâyet olursa kutuyu kendisi kaldırma sözüyle deneme önerir ve çoğunluğun onayını alır.',
     'Komşularını hiç dinlemeyen inatçı bir tutum', 'Kaygıları ciddiye alan uzlaşmacı bir tutum', 'Kararı tümüyle başkasına bırakan bir tutum', 'Tartışmadan kaçıp vazgeçen bir tutum', 'B', 2),
    ('d7b50000-0000-5000-8000-000000000124'::uuid, '26590948-2bd2-5abb-86cd-1863f06ff8bf'::uuid, 'Kompost kutusu neden doğrudan toprağın üstüne konuldu?', 1, 2, 3, 'Altı açık kutu toprağın üstüne konunca solucanlar ve küçük canlılar yığına aşağıdan ulaşabiliyordu.',
     'Kutu rüzgârda devrilmesin diye', 'Yağmur suyu içeri girmesin diye', 'Bahçedeki gölge korunabilsin diye', 'Solucanlar alttan girebilsin diye', 'D', 3),
    ('d7b50000-0000-5000-8000-000000000125'::uuid, '26590948-2bd2-5abb-86cd-1863f06ff8bf'::uuid, 'Hatalı atılan atıklar karşısında Sevgi Hanım''ın tutumu neyi gösterir?', 2, 4, 3, 'Yanlış atıkları sessizce ayıklar, kimseyi suçlamaz; listeyi büyütüp resimler ekler.',
     'Komşularına sert uyarılar yazdığını', 'İşi bütünüyle bırakmayı düşündüğünü', 'Hataları yönetime şikâyet ettiğini', 'Suçlamadan yol göstermeyi seçtiğini', 'D', 4),
    ('d7b50000-0000-5000-8000-000000000126'::uuid, '26590948-2bd2-5abb-86cd-1863f06ff8bf'::uuid, 'Yığın çok ıslak kalıp koku yaptığında ne yapıldı?', 1, 2, 3, 'Yığına bolca kuru yaprak eklenip bel küreğiyle karıştırıldı; hava girince koku birkaç günde kayboldu.',
     'Üstüne bol su dökülüp bekletildi', 'Kapak sıkıca kapatılıp bırakıldı', 'Kuru yaprak katılıp karıştırıldı', 'Yığının yarısı çöpe atıldı', 'C', 5),
    ('d7b50000-0000-5000-8000-000000000127'::uuid, '26590948-2bd2-5abb-86cd-1863f06ff8bf'::uuid, 'Halit Bey''in sonunda karıştırma işini üstlenmesi neyi gösterir?', 2, 4, 3, 'Kokudan endişe eden Halit Bey, yığından yükselen buharı görünce şaşırır, öğrenir ve karıştırmayı kendisi üstlenir.',
     'Sevgi Hanım''ın onu zorladığını', 'Kutuyu kaldırmak için fırsat aradığını', 'İlk kaygısının yerini merakın aldığını', 'Yöneticinin ona görev verdiğini', 'C', 6),
    ('d7b50000-0000-5000-8000-000000000128'::uuid, '26590948-2bd2-5abb-86cd-1863f06ff8bf'::uuid, 'Yazara göre kompost çalışmasının asıl kazancı nedir?', 3, 5, 3, 'Sevgi Hanım için asıl kazanç, yalnızca asansörde selamlaştığı komşularıyla bahçede sohbet eder hâle gelmesidir.',
     'Komşuluk bağlarının güçlenmesi', 'Çöp torbası sayısının azalması', 'Bahçede domates yetiştirilmesi', 'İkinci bir kutunun alınması', 'A', 7),
    ('d7b50000-0000-5000-8000-000000000129'::uuid, '3111f7a0-526c-59c3-8cb3-c67ae3c7d366'::uuid, 'Öğrencilere atölyeye girişte ne söylendi?', 1, 1, 3, 'Girişte hiçbir şeye dokunmamaları ve çantalarını kapının yanına bırakmaları söylendi.',
     'Eşyalara el sürmemeleri', 'Fırına yakın durmaları', 'Kapıyı açık bırakmaları', 'Fotoğraf çekmemeleri', 'A', 0),
    ('d7b50000-0000-5000-8000-000000000130'::uuid, '3111f7a0-526c-59c3-8cb3-c67ae3c7d366'::uuid, 'Atölyedeki fırın neden çoğu zaman sürekli yanar?', 1, 2, 3, 'Usta, fırını söndürüp yeniden ısıtmanın çok uzun sürdüğünü söyledi.',
     'Atölye geceleri de satış yaptığı için', 'Ateşi söndürmek yasak olduğu için', 'Yeniden ısıtmak çok uzun sürdüğü için', 'Kum yalnızca gece eridiği için', 'C', 1),
    ('d7b50000-0000-5000-8000-000000000131'::uuid, '3111f7a0-526c-59c3-8cb3-c67ae3c7d366'::uuid, 'Rasim Usta erimiş camı nasıl şişirdi?', 1, 2, 3, 'Borunun öbür ucuna hafifçe üfledi; cam bir balon gibi şişti.',
     'Bir körükle hava basarak', 'Camı suya batırıp çekerek', 'İçi boş borudan üfleyerek', 'Çelik masada döverek', 'C', 2),
    ('d7b50000-0000-5000-8000-000000000132'::uuid, '3111f7a0-526c-59c3-8cb3-c67ae3c7d366'::uuid, 'Boruyu sürekli çevirmek neden gereklidir?', 2, 4, 3, 'Boru durursa erimiş cam yerçekimiyle bir yana sarkar ve biçim bozulur.',
     'Cam daha çabuk soğusun diye', 'Ustanın elleri yorulmasın diye', 'Cam daha parlak görünsün diye', 'Cam bir yana sarkmasın diye', 'D', 3),
    ('d7b50000-0000-5000-8000-000000000133'::uuid, '3111f7a0-526c-59c3-8cb3-c67ae3c7d366'::uuid, 'Yeni yapılan vazonun ayrı bir fırında yavaşça soğutulmasının nedeni nedir?', 2, 4, 3, 'Usta''ya göre sıcak cam birden soğursa çatlayabilir; parçalar saatlerce yavaş yavaş soğutulur.',
     'Vazonun rengini koyulaştırmak', 'Ani soğuyan camın çatlaması', 'Rafların henüz dolu olması', 'Camın yeniden şekillenmesi', 'B', 4),
    ('d7b50000-0000-5000-8000-000000000134'::uuid, '3111f7a0-526c-59c3-8cb3-c67ae3c7d366'::uuid, 'Mert''in ilk denemesinin başarısız olması ona ne öğretti?', 2, 4, 3, 'Çok hafif üflediği için cam şişmez; ikinci denemede başarır ve işin güç ve dikkat istediğini anlar.',
     'İşin hem güç hem dikkat istediğini', 'Gözlüğün işi zorlaştırdığını', 'Camın bu sefer soğuk olduğunu', 'Ustanın onu yanlış yönlendirdiğini', 'A', 5),
    ('d7b50000-0000-5000-8000-000000000135'::uuid, '3111f7a0-526c-59c3-8cb3-c67ae3c7d366'::uuid, '"Gözünü eğitmeden elini eğitemezsin" sözü neyi anlatır?', 2, 5, 3, 'Usta ilk yıl yalnızca ateşi besleyip ustasını izlemişti; iyi iş önce dikkatle gözlemeyi gerektirir.',
     'Gözlüğün her işte şart olduğunu', 'Çırakların hiç çalışmaması gerektiğini', 'El becerisinin doğuştan geldiğini', 'Ustalığın önce gözlemle başladığını', 'D', 6),
    ('d7b50000-0000-5000-8000-000000000136'::uuid, '3111f7a0-526c-59c3-8cb3-c67ae3c7d366'::uuid, 'Metnin sonunda Ela''nın düşüncesi neyi gösterir?', 3, 5, 3, 'Masasına düşen mavi gölgeyi görünce bir avuç kumun ne kadar uzun bir yolculuk yaptığını düşünür.',
     'Cam kuşu pahalı bulduğuna pişmanlığını', 'Sıradan kumun dönüşümüne hayranlığını', 'Cam ustası olmaya karar verdiğini', 'Güneş ışığından rahatsız olduğunu', 'B', 7),
    ('d7b50000-0000-5000-8000-000000000137'::uuid, '3442e156-0a5f-5562-8403-c531a2d318ef'::uuid, 'Defne iki hafta içinde Ay''ı hangi sırayla gördü?', 1, 1, 5, 'İlk paragrafa göre önce ince bir hilal, bir hafta sonra yarım aydınlık Ay, bir hafta sonra da dolunay gördü.',
     'Dolunay, yarım, hilal', 'Yarım, hilal, dolunay', 'Hilal, yarım, dolunay', 'Hilal, dolunay, yarım', 'C', 0),
    ('d7b50000-0000-5000-8000-000000000138'::uuid, '3442e156-0a5f-5562-8403-c531a2d318ef'::uuid, 'Nihat Bey hangi yaygın yanlışı düzeltti?', 2, 4, 5, 'Pek çok kişi karanlık kısmı Dünya''nın gölgesi sanır; oysa değişen, aydınlık yarının Dünya''dan ne kadarının göründüğüdür.',
     'Ay''ın Güneş''ten büyük olduğunu düşünmeyi', 'Ay''ın her gece aynı saatte doğduğunu sanmayı', 'Karanlık kısmı Dünya''nın gölgesi sanmayı', 'Ay''ın Güneş''in çevresinde döndüğünü düşünmeyi', 'C', 1),
    ('d7b50000-0000-5000-8000-000000000139'::uuid, '3442e156-0a5f-5562-8403-c531a2d318ef'::uuid, 'Deneyde lamba neyi temsil ediyordu?', 1, 2, 5, 'Üçüncü paragrafa göre lamba Güneş''i, Defne''nin başı Dünya''yı, top ise Ay''ı temsil ediyordu.',
     'Güneş''i', 'Ay''ı', 'Dünya''yı', 'Yıldızları', 'A', 2),
    ('d7b50000-0000-5000-8000-000000000140'::uuid, '3442e156-0a5f-5562-8403-c531a2d318ef'::uuid, 'Top lambayla Defne''nin arasındayken neden hemen hiç ışık görülmedi?', 2, 4, 5, 'Topun aydınlık yüzü lambaya bakıyordu; Defne yalnızca karanlık yüzü gördü. Bu yeni ay evresidir.',
     'Lamba o anda topu hiç aydınlatmıyordu', 'Defne''nin başı topa gölge düşürüyordu', 'Top bu konumda çok uzakta kalıyordu', 'Işıklı yüzü lambaya dönük duruyordu', 'D', 3),
    ('d7b50000-0000-5000-8000-000000000141'::uuid, '3442e156-0a5f-5562-8403-c531a2d318ef'::uuid, 'Eski toplumlar Ay''ın evrelerini ne amaçla izlemişti?', 1, 2, 5, 'Pek çok eski toplum zamanı ölçmek için Ay''ın evrelerini izlemişti; çiftçiler ve denizciler de planlarını buna göre yaptı.',
     'Hava tahmini için', 'Gün saymak için', 'Yön bulmak için', 'Ay''a gitmek için', 'B', 4),
    ('d7b50000-0000-5000-8000-000000000142'::uuid, '3442e156-0a5f-5562-8403-c531a2d318ef'::uuid, 'Dünya''dan Ay''ın hep aynı yüzünün görülmesinin nedeni nedir?', 2, 4, 5, 'Ay, Dünya çevresindeki bir turda kendi ekseni çevresinde de bir kez döner; iki hareket aynı sürede tamamlanır.',
     'Ay''ın iki dönüşünün de aynı sürmesi', 'Ay''ın kendi çevresinde hiç dönmemesi', 'Ay''ın öbür yüzünün hep karanlık olması', 'Dünya''nın Ay''dan daha yavaş dönmesi', 'A', 5),
    ('d7b50000-0000-5000-8000-000000000143'::uuid, '3442e156-0a5f-5562-8403-c531a2d318ef'::uuid, 'Ay tutulmasının her ay yaşanmamasının nedeni nedir?', 2, 4, 5, 'Ay''ın yörüngesi biraz eğiktir; çoğu dolunayda Ay, Dünya''nın gölgesinin biraz üstünden ya da altından geçer.',
     'Dolunayın her ay görülmemesi', 'Dünya''nın gölgesinin küçük olması', 'Güneş''in bazen Ay''ı aydınlatmaması', 'Ay''ın yolunun hafifçe eğik olması', 'D', 6),
    ('d7b50000-0000-5000-8000-000000000144'::uuid, '3442e156-0a5f-5562-8403-c531a2d318ef'::uuid, 'Defne''nin bulutlu akşamları soru işaretiyle göstermesi hangi tutumu yansıtır?', 3, 5, 5, 'Defne o akşamlar için tahminle çizmek yerine boş kareleri işaretler; gözlemi dürüstçe kaydeder.',
     'Çizim yapmaktan sıkıldığını', 'Uydurmadan kayıt tutmayı', 'Gözlemi yarıda bırakmayı', 'Bulutları da çizmek istemeyi', 'B', 7),
    ('d7b50000-0000-5000-8000-000000000145'::uuid, '372a4ea1-386a-5a10-836d-42bdde92073a'::uuid, 'Yazara göre ahtapotu asıl ilginç kılan nedir?', 2, 4, 2, 'İlk paragrafa göre ahtapotu asıl ilginç kılan, gövdesinin içinde ve derisinde saklı özellikleridir.',
     'Sekiz uzun kolu ve iri gözleri', 'İç yapısı ve derisinin sırları', 'Denizin derinlerinde yaşaması', 'Başka hayvanlara çok benzemesi', 'B', 0),
    ('d7b50000-0000-5000-8000-000000000146'::uuid, '372a4ea1-386a-5a10-836d-42bdde92073a'::uuid, 'Ahtapotun kanı neden mavimsi görünür?', 1, 2, 2, 'Kanında oksijen taşıyan madde bakır içerir; bizimkinde ise demir vardır ve kan kırmızı görünür.',
     'Kanında demir çok fazla olduğu için', 'Kanında bakırlı bir madde olduğu için', 'Üç ayrı kalbi kanı hızla pompaladığı için', 'Deniz suyu kanına karıştığı için', 'B', 1),
    ('d7b50000-0000-5000-8000-000000000147'::uuid, '372a4ea1-386a-5a10-836d-42bdde92073a'::uuid, 'Ahtapotun dar aralıklardan geçebilmesini sağlayan nedir?', 2, 4, 2, 'Vücudunda hiç kemik yoktur; tek sert bölüm gagasıdır. Gaga sığdığı sürece dar bir delikten geçebilir.',
     'Gagası dışında sert yeri olmaması', 'Kollarını gövdesinden ayırabilmesi', 'Rengini kayaya benzetebilmesi', 'Suyu hızla dışarı fışkırtması', 'A', 2),
    ('d7b50000-0000-5000-8000-000000000148'::uuid, '372a4ea1-386a-5a10-836d-42bdde92073a'::uuid, 'Metne göre vantuzlar hangi işi de görür?', 1, 2, 2, 'Vantuzlar tutunmayı ve avı yakalamayı sağlar; dokunduğu şeyin tadını da alabilir.',
     'Suya mürekkep püskürtmek', 'Suyu içine çekip fışkırtmak', 'Derinin rengini değiştirmek', 'Dokunduğunun tadını almak', 'D', 3),
    ('d7b50000-0000-5000-8000-000000000149'::uuid, '372a4ea1-386a-5a10-836d-42bdde92073a'::uuid, 'Ahtapot suyu fışkırtarak ilerlemeyi neden yalnızca kısa kaçışlarda kullanır?', 2, 4, 2, 'Fışkırtma yöntemi çok hızlıdır ama ahtapotu çabuk yorar; bu yüzden kısa kaçışlarda kullanılır.',
     'Bu yöntem çok yavaş kaldığı için', 'Kolları yorulduğunda işe yaradığı için', 'Yürümek ondan daha hızlı olduğu için', 'Hızlı olsa da onu çabuk yorduğu için', 'D', 4),
    ('d7b50000-0000-5000-8000-000000000150'::uuid, '372a4ea1-386a-5a10-836d-42bdde92073a'::uuid, 'Ahtapot rengini nasıl değiştirir?', 1, 2, 2, 'Derisinde renk taşıyan çok sayıda küçük hücre vardır; ahtapot bunları büyütüp küçülterek rengini değiştirir.',
     'Suya koyu mürekkep püskürterek', 'Kollarındaki vantuzları açarak', 'Derideki küçük hücreleri oynatarak', 'Kabuk ve taşların arkasına girerek', 'C', 5),
    ('d7b50000-0000-5000-8000-000000000151'::uuid, '372a4ea1-386a-5a10-836d-42bdde92073a'::uuid, 'Akvaryumda yapılan gözlemler ahtapot hakkında neyi gösterir?', 2, 4, 2, 'Kapaklı kavanozları açtıkları ve labirentten çıkış yolunu buldukları gözlenmiştir; bu, zekâlarını gösterir.',
     'Akvaryumda çok uzun yaşadığını', 'Kavanozdaki yiyeceğe ilgi duymadığını', 'Sorun çözebilen bir canlı olduğunu', 'Labirentte hep yolunu kaybettiğini', 'C', 6),
    ('d7b50000-0000-5000-8000-000000000152'::uuid, '372a4ea1-386a-5a10-836d-42bdde92073a'::uuid, 'Son paragrafa göre bilim insanları ahtapotu neden incelemeyi sürdürüyor?', 3, 5, 2, 'Ahtapot, zekânın ve uyumun doğada ne kadar farklı biçimlerde ortaya çıkabileceğini gösterir.',
     'Zekânın çeşitliliğini anlamak için', 'Ömrünü uzatmanın yolunu bulmak için', 'Mürekkebinden ilaç yapmak için', 'Ahtapot sayısını artırmak için', 'A', 7),
    ('d7b50000-0000-5000-8000-000000000153'::uuid, '39e9b2a3-c32c-57ad-8361-6447ae255df3'::uuid, 'Selim Bey''e göre iyi bir münazaracı nasıl biridir?', 1, 2, 4, 'İyi münazaracı sesini yükselten değil, gerekçesini en açık biçimde ortaya koyan ve karşı tarafı dikkatle dinleyen kişidir.',
     'Sesini en çok yükseltebilen', 'Gerekçesini sunup iyi dinleyen', 'Her tartışmayı mutlaka kazanan', 'Karşı tarafı hızla susturan', 'B', 0),
    ('d7b50000-0000-5000-8000-000000000154'::uuid, '39e9b2a3-c32c-57ad-8361-6447ae255df3'::uuid, 'Tarafların kurayla belirlenmesinin amacı nedir?', 2, 4, 4, 'Öğrenciler yalnızca inandıkları görüşleri değil, farklı bakış açılarını da anlamayı öğrenmelidir.',
     'Takımların eşit olmasını sağlamak', 'Hakemlerin işini epey kolaylaştırmak', 'Öğrencilerin hiç hazırlanmamasını sağlamak', 'Başka görüşleri de anlamayı öğretmek', 'D', 1),
    ('d7b50000-0000-5000-8000-000000000155'::uuid, '39e9b2a3-c32c-57ad-8361-6447ae255df3'::uuid, 'Selim Bey''in kurayı değiştirmeyip gülümsemesi neyi anlatır?', 2, 4, 4, 'Öğretmenine göre en iyi hazırlık çoğu zaman en zorlandığımız tarafta yapılır.',
     'Ece''nin görüşünü hiç önemsemediğini', 'Kurayı değiştirmeye yetkisi olmadığını', 'Zor tarafın daha çok şey öğrettiğini', 'Önergenin yanlış seçildiğini düşündüğünü', 'C', 2),
    ('d7b50000-0000-5000-8000-000000000156'::uuid, '39e9b2a3-c32c-57ad-8361-6447ae255df3'::uuid, 'Onur hazırlığa nereden başlamayı önerdi?', 1, 2, 4, 'Onur önce karşı tarafın en güçlü gerekçelerini yazmayı önerdi; onları anlamadan yanıt veremezlerdi.',
     'Kendi en güçlü örneklerinden', 'Rakibin güçlü gerekçelerinden', 'Konuşmanın son cümlesinden', 'Hakemlerin puan ölçütlerinden', 'B', 3),
    ('d7b50000-0000-5000-8000-000000000157'::uuid, '39e9b2a3-c32c-57ad-8361-6447ae255df3'::uuid, 'Ece konuşmasının merkezine hangi ayrımı koydu?', 1, 2, 4, 'Bir öğretmen ödevin miktarı ile varlığının ayrı şeyler olduğunu söyledi; Ece bu ayrımı merkeze koydu.',
     'Ödevin miktarıyla varlığının farkını', 'Öğretmenle öğrenci arasındaki farkı', 'Ortaokul ile lise arasındaki farkı', 'Hafta içi ile hafta sonu arasındaki farkı', 'A', 4),
    ('d7b50000-0000-5000-8000-000000000158'::uuid, '39e9b2a3-c32c-57ad-8361-6447ae255df3'::uuid, 'Ece''nin konuşmaya karşı tarafın haklı noktasını kabul ederek başlamasının etkisi neydi?', 2, 5, 4, 'Ece bu açılışın dinleyicilerin güvenini kazandırdığını hissetti; hakemler de bunu günün en etkili hamlelerinden saydı.',
     'Hakemlerin kuralı bozduğunu düşünmesi', 'Karşı takımın konuşmaktan vazgeçmesi', 'Salondakileri kendine inandırması', 'Salonun hemen alkışa boğulması', 'C', 5),
    ('d7b50000-0000-5000-8000-000000000159'::uuid, '39e9b2a3-c32c-57ad-8361-6447ae255df3'::uuid, 'Ece''nin eleştiriye verdiği karşılık nasıldı?', 2, 4, 4, 'Ece söz sırasını bekledi, eleştiriyi not aldı ve sesini yükseltmeden örneğinin kaynağını anlattı.',
     'Bekleyip sakin bir yanıt verdi', 'Hemen ayağa kalkıp itiraz etti', 'Hakemlere şikâyette bulundu', 'Örneğini hiç savunmadan geri çekti', 'A', 6),
    ('d7b50000-0000-5000-8000-000000000160'::uuid, '39e9b2a3-c32c-57ad-8361-6447ae255df3'::uuid, 'Metnin sonunda Ece''nin münazaradan kazandığı en önemli şey nedir?', 3, 5, 4, 'Ece artık konuya yalnızca kendi penceresinden bakmıyordu; münazara ona karşısındakini dinlemeyi öğretmişti.',
     'Hafta sonu ödevinden kurtulmak', 'Kulübün en iyi konuşmacısı olmak', 'Karşılaşmayı az farkla kazanmak', 'Konuya başka gözlerle bakabilmek', 'D', 7),
    ('d7b50000-0000-5000-8000-000000000161'::uuid, '3d283ad5-2e0c-55be-87cb-66a7885654da'::uuid, 'Nermin Hanım ilk gün Berk''e neler verdi?', 1, 1, 2, 'İlk paragrafa göre Nermin Hanım Berk''e bir çift eldiven, bir şapka ve bir su şişesi verdi.',
     'Hortum, kürek ve iş eldiveni', 'Saksı, toprak ve tohum', 'Şapka, defter ve kalem', 'Eldiven, şapka ve su şişesi', 'D', 0),
    ('d7b50000-0000-5000-8000-000000000162'::uuid, '3d283ad5-2e0c-55be-87cb-66a7885654da'::uuid, 'Berk''in ilk sulamasının sorunu neydi?', 2, 4, 2, 'Toprak yalnızca üstten ıslanmış, altı kupkuru kalmıştı; Berk hızlı suladığı için su derine inmemişti.',
     'Saksılara fazla su verilmesi', 'Suyun alttaki toprağa inmemesi', 'Bazı sıraların atlanmış olması', 'Hortumun su kaçırmış olması', 'B', 1),
    ('d7b50000-0000-5000-8000-000000000163'::uuid, '3d283ad5-2e0c-55be-87cb-66a7885654da'::uuid, 'Bir saksının yeterince sulandığı nasıl anlaşılır?', 1, 2, 2, 'Nermin Hanım''a göre saksının altındaki delikten su damlayınca o saksı tamam demektir.',
     'Toprağın üstü kararınca', 'Alt delikten su sızınca', 'Yapraklar ıslanınca', 'Yarım saat dolunca', 'B', 2),
    ('d7b50000-0000-5000-8000-000000000164'::uuid, '3d283ad5-2e0c-55be-87cb-66a7885654da'::uuid, 'Sıcak günlerde sulama neden sabah erkenden yapılmalıdır?', 1, 2, 2, 'Öğle güneşinde verilen suyun bir kısmı hemen buharlaşır; ayrıca sıcakta ıslanan yapraklar zarar görebilir.',
     'Fidanlık öğlen müşterilere açıldığı için', 'Sabah suyu daha temiz olduğu için', 'Öğlen suyun bir kısmı uçup gittiği için', 'Hortumlar öğlen çok ısındığı için', 'C', 3),
    ('d7b50000-0000-5000-8000-000000000165'::uuid, '3d283ad5-2e0c-55be-87cb-66a7885654da'::uuid, 'Kökleri saksı deliğinden çıkan fidanlar hakkında ne söylenebilir?', 2, 4, 2, 'Bazı fidanlar saksılarına sığmıyordu; daha büyük saksılara alınıp yeni toprak eklendi.',
