    ('d7b50000-0000-5000-8000-000000000168'::uuid, '3d283ad5-2e0c-55be-87cb-66a7885654da'::uuid, 'Berk''in limon fidanı için kendine sorduğu soru neyi gösterir?', 3, 5, 2, 'Bir hafta önce aklına bile gelmeyecek bu soru, bitkinin ihtiyaçlarını düşünmeyi öğrendiğini gösterir.',
     'Bakış açısının değiştiğini', 'Hediyeyi pek beğenmediğini', 'Odasının çok karanlık olduğunu', 'Fidanı geri vermek istediğini', 'A', 7),
    ('d7b50000-0000-5000-8000-000000000169'::uuid, '424581fa-94c3-5ba3-8fc5-4570c6381723'::uuid, 'Akvaryumdaki balıklara kim bakacaktı?', 1, 1, 3, 'İlk paragrafa göre Kenan Bey, balıklara öğrencilerin bakacağını söyledi.',
     'Sınıftaki çocuklar', 'Okulun hizmetlisi', 'Yalnızca Kenan Bey', 'Okul müdürünün kendisi', 'A', 0),
    ('d7b50000-0000-5000-8000-000000000170'::uuid, '424581fa-94c3-5ba3-8fc5-4570c6381723'::uuid, 'Kenan Bey balıklara neden yalnızca bir tutam yem verilmesini istedi?', 1, 2, 3, 'Kenan Bey, bir tutamdan fazlasının balıklara iyi gelmeyeceğini söyledi.',
     'Yem çok pahalı olduğu için', 'Balıklar yemi sevmediği için', 'Akvaryum küçük olduğu için', 'Fazlası zarar verdiği için', 'D', 1),
    ('d7b50000-0000-5000-8000-000000000171'::uuid, '424581fa-94c3-5ba3-8fc5-4570c6381723'::uuid, 'Arda''nın balıklara üç kez yem vermesinin nedeni nedir?', 2, 4, 3, 'Arda balıkların çok aç olduğunu düşündü; yem hemen yenince bir tutam daha verdi.',
     'Listeyi okumaması', 'Onları aç sanması', 'Kenan Bey''in istemesi', 'Yemi bitirmek istemesi', 'B', 2),
    ('d7b50000-0000-5000-8000-000000000172'::uuid, '424581fa-94c3-5ba3-8fc5-4570c6381723'::uuid, 'Ertesi sabah suyun bulanık olmasının nedeni neydi?', 2, 4, 3, 'Kenan Bey artan yemin suyun içinde çürüdüğünü ve suyu kirlettiğini anlattı.',
