    ('d7b50000-0000-5000-8000-000000000180'::uuid, '43a28758-86fc-566b-83bf-a0d5fec4fa78'::uuid, 'Kitap neden kütüphaneye geri gelmemişti?', 1, 2, 1, 'Damla kitabı kardeşine vermişti; ikisi de kitabın kütüphaneye ait olduğunu unutmuştu.',
