    ('d7b50000-0000-5000-8000-000000000361'::uuid, '8a4e983a-47db-5a46-8c8d-932e4acdc159'::uuid, 'Annenin ekim ayında verdiği karar neydi?', 1, 1, 1, 'İlk paragrafa göre harçlık artık her gün değil, haftada bir kez verilecekti.',
     'Harçlığın tamamen kesilmesi', 'Harçlığın haftalık verilmesi', 'Harçlığın iki katına çıkması', 'Harçlığın ablaya verilmesi', 'B', 0),
    ('d7b50000-0000-5000-8000-000000000362'::uuid, '8a4e983a-47db-5a46-8c8d-932e4acdc159'::uuid, 'Perşembe sabahı cüzdanın boş olmasının nedeni nedir?', 2, 4, 1, 'Pazartesiden itibaren tost, meyve suyu ve kalemlere düşünmeden harcamış, hafta bitmeden para tükenmişti.',
     'Parayı plansızca harcaması', 'Cüzdanını okulda kaybetmesi', 'Ablasına borç vermiş olması', 'Annesinin az para vermesi', 'A', 1),
    ('d7b50000-0000-5000-8000-000000000363'::uuid, '8a4e983a-47db-5a46-8c8d-932e4acdc159'::uuid, 'Abla para sorununa ne çözüm önerdi?', 1, 2, 1, 'Ablası paranın nereye gittiği yazılırsa daha kolay yönetileceğini söyledi.',
     'Harcamaları deftere yazmak', 'Annesinden çok istemek', 'Kantine hiç ama hiç gitmemek', 'Arkadaşlarından ödünç almak', 'A', 2),
    ('d7b50000-0000-5000-8000-000000000364'::uuid, '8a4e983a-47db-5a46-8c8d-932e4acdc159'::uuid, 'Defter tutunca hangi bilgi şaşırtıcı çıktı?', 1, 2, 1, 'Paranın yarısından fazlası atıştırmalıklara gitmişti.',
     'Kırtasiyeye hiç para harcanmaması', 'Eğlenceye en çok paranın gitmesi', 'Paranın çoğunun yiyeceğe gitmesi', 'Gelen paranın beklenenden az olması', 'C', 3),
    ('d7b50000-0000-5000-8000-000000000365'::uuid, '8a4e983a-47db-5a46-8c8d-932e4acdc159'::uuid, 'Evden meyve ve su götürmeye başlamak neyi sağladı?', 2, 4, 1, 'Kantine yalnızca iki gün gitti; hafta sonunda cuma akşamı bile cüzdanında para kalmıştı.',
     'Okul eşyalarını artırdı', 'Arkadaşlarını kızdırdı', 'Deftere yazmayı bıraktırdı', 'Kantin harcamasını azalttı', 'D', 4),
    ('d7b50000-0000-5000-8000-000000000366'::uuid, '8a4e983a-47db-5a46-8c8d-932e4acdc159'::uuid, 'Birikim kutusundaki para ne için toplandı?', 1, 2, 1, 'Uzun zamandır istediği bisiklet kaskı için biriktirmeye karar verdi.',
     'Renkli kalemler için', 'Okul gezisinin ücreti için', 'Ablasına bir hediye için', 'Bir bisiklet kaskı için', 'D', 5),
    ('d7b50000-0000-5000-8000-000000000367'::uuid, '8a4e983a-47db-5a46-8c8d-932e4acdc159'::uuid, 'Arkadaşları alışveriş yaparken beklemesi neyi gösterir?', 2, 4, 1, 'İlk haftalar kolay geçmedi; ama birikim için harcamadan beklemeyi göze aldı.',
     'Arkadaşlarına küstüğünü', 'Parasını kaybetmiş olduğunu', 'Hedefi için sabrettiğini', 'Kantini hiç sevmediğini', 'C', 6),
    ('d7b50000-0000-5000-8000-000000000368'::uuid, '8a4e983a-47db-5a46-8c8d-932e4acdc159'::uuid, 'Metnin sonundaki düşünce hangisidir?', 3, 5, 1, 'Kaskı kendi parasıyla alır ve plan yapmanın para azaldığında değil, daha elindeyken gerektiğini anlar.',
     'Harçlık hiç harcanmamalıdır', 'Plan, para varken yapılmalıdır', 'Kask almak gereksiz bir harcamadır', 'Para azalınca yardım istenmelidir', 'B', 7),
    ('d7b50000-0000-5000-8000-000000000369'::uuid, '8af34c46-0b38-5e48-87cc-d610dac4fd5a'::uuid, 'Kirpi korktuğunda ne yapar?', 1, 1, 2, 'İlk paragrafa göre kirpi korktuğunda top gibi kıvrılır; dikenleri onu korur.',
     'Hızla koşup kaçar', 'Yüksek ses çıkarır', 'Toprağa gömülür', 'Yumak gibi büzülür', 'D', 0),
    ('d7b50000-0000-5000-8000-000000000370'::uuid, '8af34c46-0b38-5e48-87cc-d610dac4fd5a'::uuid, 'Kirpi yiyeceğini çoğu zaman nasıl bulur?', 1, 2, 2, 'Kirpinin burnu çok iyi koku alır; yiyeceğini çoğu zaman kokusundan bulur.',
     'Dinleyerek', 'Bakarak', 'Koklayarak', 'Dokunarak', 'C', 1),
    ('d7b50000-0000-5000-8000-000000000371'::uuid, '8af34c46-0b38-5e48-87cc-d610dac4fd5a'::uuid, 'Kirpi sonbaharda neden daha çok yer?', 2, 3, 2, 'Kışın yiyecek bulmak zorlaşır; kirpi vücudunda yağ biriktirir ve bu yağ kışın yiyeceği olur.',
     'Yuvası küçük kaldığı için', 'Soğuk günlere hazırlık için', 'Böcekler çoğaldığı için', 'Dikenleri hiç dökülmesin diye', 'B', 2),
    ('d7b50000-0000-5000-8000-000000000372'::uuid, '8af34c46-0b38-5e48-87cc-d610dac4fd5a'::uuid, 'Kirpi kış yuvasını nereye yapar?', 1, 2, 2, 'Kuru yaprakları bir çalının dibine ya da bir odun yığınının altına taşır.',
     'Ağacın yüksek bir dalına', 'Çalı ya da odun dibine', 'Derenin hemen kıyısına', 'Evlerin çatı arasına', 'B', 3),
    ('d7b50000-0000-5000-8000-000000000373'::uuid, '8af34c46-0b38-5e48-87cc-d610dac4fd5a'::uuid, 'Kış uykusunda kirpinin yağı neden bütün kışa yeter?', 2, 3, 2, 'Kalbi ve nefesi yavaşlar, vücudu soğur; çok az enerji harcadığı için yağ yavaş tükenir.',
     'Bedeni çok yavaş çalışır', 'Kışın yine de çok yemek yer', 'Yuvada yiyecek saklamıştır', 'Yağı her gün yenilenir', 'A', 4),
    ('d7b50000-0000-5000-8000-000000000374'::uuid, '8af34c46-0b38-5e48-87cc-d610dac4fd5a'::uuid, 'İlkbaharda uyanan kirpi nasıldır?', 1, 2, 2, 'Kış boyunca epey zayıflamış ve çok acıkmıştır.',
     'Şişman ve tok', 'Hasta ve üzgün', 'Zayıf ve aç', 'Dinç ve tok', 'C', 5),
    ('d7b50000-0000-5000-8000-000000000375'::uuid, '8af34c46-0b38-5e48-87cc-d610dac4fd5a'::uuid, 'Metne göre kirpiye neden süt verilmemelidir?', 2, 3, 2, 'Son paragrafa göre süt kirpinin midesine dokunabilir.',
     'Mideyi bozabileceği için', 'Süt pahalı olduğu için', 'Kirpi süt içemediği için', 'Süt yuvayı ıslattığı için', 'A', 6),
    ('d7b50000-0000-5000-8000-000000000376'::uuid, '8af34c46-0b38-5e48-87cc-d610dac4fd5a'::uuid, 'Bahçede yaprak yığını bırakmak kirpiye nasıl yardım eder?', 3, 3, 2, 'Kirpi yuvasını kuru yaprak ve otlarla yapar; yaprak yığını ona güzel bir yardımdır.',
     'Onu kış uykusundan uyandırır', 'Onu bahçeden uzak tutar', 'Ona yiyecek yerine geçer', 'Ona yuva malzemesi sağlar', 'D', 7),
    ('d7b50000-0000-5000-8000-000000000377'::uuid, '933d4762-0ead-5d04-834d-3aebf345a4ec'::uuid, 'Ezgi''nin taşları dizerken yavaşlamasının nedeni nedir?', 2, 4, 5, 'Kendi oyununun takımın yerini belirleyebileceğini bilmek parmaklarının yavaş hareket etmesine yol açtı.',
     'Sonucun takımı etkileyecek olması', 'Rakibinin onu sürekli dikkatle izlemesi', 'Salondaki gürültünün çok artması', 'Taşların birbirine çok benzemesi', 'A', 0),
    ('d7b50000-0000-5000-8000-000000000378'::uuid, '933d4762-0ead-5d04-834d-3aebf345a4ec'::uuid, 'Vedat Hoca''nın otobüsteki öğüdü neydi?', 1, 2, 5, '"Rakibinizi değil, tahtayı oynayın. Önünüzde yalnızca altmış dört kare var," demişti.',
     'Açılışı çok hızlı bitirmek', 'Yalnız tahtaya odaklanmak', 'Saldırıya erken başlamak', 'Rakibin puanını öğrenmek', 'B', 1),
    ('d7b50000-0000-5000-8000-000000000379'::uuid, '933d4762-0ead-5d04-834d-3aebf345a4ec'::uuid, 'Oyundan önce Ezgi''yi biraz sakinleştiren ne oldu?', 1, 2, 5, 'Kâğıdının köşesine adını, tarihi ve tur numarasını yazmak gibi alışılmış bir hareket onu sakinleştirdi.',
     'Telefonunu kapatıp saklamak', 'Hakemle kısaca konuşmak', 'Takımına uzaktan el sallamak', 'Kâğıda bilgilerini yazmak', 'D', 2),
    ('d7b50000-0000-5000-8000-000000000380'::uuid, '933d4762-0ead-5d04-834d-3aebf345a4ec'::uuid, 'Ezgi''nin açılıştaki hızı sonunda neden bir dezavantaja dönüştü?', 2, 4, 5, 'Başta kazandığı süre ezber bitince uzun düşünmelerle tükendi; oyun sonunda her hamleye birkaç dakikası kaldı.',
     'Sonraki hamlelere vakit kalmadı', 'Rakibe zaman cezası verilmedi', 'Hakem saati yanlış zamanda başlattı', 'Açılış hamleleri hatalı çıktı', 'A', 3),
    ('d7b50000-0000-5000-8000-000000000381'::uuid, '933d4762-0ead-5d04-834d-3aebf345a4ec'::uuid, 'Vedat Hoca''nın her hamleden önce sorulacak sorusu neydi?', 1, 2, 5, '"Her hamleden önce kendine sor; rakip son hamlesiyle neyi tehdit ediyor?"',
     'Hangi taşla en hızlı saldırabilirim?', 'Takım arkadaşlarım şu an kaçıncı sırada?', 'Rakibimin puanı benden yüksek mi?', 'Rakibin son hamlesi neyi tehdit ediyor?', 'D', 4),
    ('d7b50000-0000-5000-8000-000000000382'::uuid, '933d4762-0ead-5d04-834d-3aebf345a4ec'::uuid, 'Ezgi''nin vezir saldırısından vazgeçmesi neden doğru karardı?', 2, 5, 5, 'Rakibin piyon hamlesi saldırıyı bekliyordu; vezir ilerlerse arkadaki fil birkaç hamle sonra kaybedilebilirdi.',
     'Vezir o karede hareket edemiyordu', 'Saldırı, filini savunmasız bırakırdı', 'Saldırı hakem tarafından yasaklandı', 'Rakip beraberliği çok önceden önermişti', 'B', 5),
    ('d7b50000-0000-5000-8000-000000000383'::uuid, '933d4762-0ead-5d04-834d-3aebf345a4ec'::uuid, 'Ezgi sonraki turnuva için neye çalışmaya karar verdi?', 1, 2, 5, 'Açılış ezberinden çok süresini nasıl kullanacağını ve heyecanını nasıl yöneteceğini çalışmaya karar verdi.',
     'Yeni açılış ezberlerine', 'Vezirle saldırı taktiklerine', 'Saati ve kaygıyı yönetmeye', 'Rakiplerin eski oyunlarına', 'C', 6),
    ('d7b50000-0000-5000-8000-000000000384'::uuid, '933d4762-0ead-5d04-834d-3aebf345a4ec'::uuid, '"En zor hamle, oynamadığın hamleydi" sözü neyi anlatır?', 3, 5, 5, 'Ezgi''nin oynamadığı vezir hamlesi büyük ihtimalle oyunu kaybettirecekti; onu oynamamak en zor ve doğru karardı.',
     'Hamle yapmamanın kural dışı olduğunu', 'Beraberliğin bir yenilgi sayıldığını', 'Cazip bir hatadan kaçınmanın değerini', 'Vezirin oyundaki en zayıf taş olduğunu', 'C', 7),
    ('d7b50000-0000-5000-8000-000000000385'::uuid, '949b29a3-ad44-59ba-8383-f7c182db0d09'::uuid, 'Yağmur nasıl sakatlandı?', 1, 1, 3, 'Antrenmanda smaçtan sonra yere yanlış basmış ve bileğini burkmuştu.',
     'İnişte ayağını yanlış koyarak', 'Maçta rakiple çarpışarak', 'Merdivenden kayıp düşerek', 'Servis atarken omzunu burkarak', 'A', 0),
    ('d7b50000-0000-5000-8000-000000000386'::uuid, '949b29a3-ad44-59ba-8383-f7c182db0d09'::uuid, 'Nesrin Hanım Yağmur''a hangi görevi önerdi?', 1, 2, 3, 'Takımın, servis ve sayıları kaydedecek bir istatistik sorumlusuna ihtiyacı vardı.',
     'Yedek kulübesinde beklemek', 'Maç verilerini kayda geçirmek', 'Genç oyunculara ders vermek', 'Takımın formalarını düzenlemek', 'B', 1),
    ('d7b50000-0000-5000-8000-000000000387'::uuid, '949b29a3-ad44-59ba-8383-f7c182db0d09'::uuid, 'Yağmur ikinci maçta neden kısaltmalar kullanmaya başladı?', 2, 4, 3, 'İlk maçta top çok hızlı gidip geldiği için kalemi yetişmemiş, her şeyi yazmaya çalışırken geride kalmıştı.',
     'Antrenörü kısaltma istediği için', 'Çizelgedeki sütunlar az olduğu için', 'Arkadaşları kolay okusun diye', 'Oyunun hızına ayak uydurmak için', 'D', 2),
    ('d7b50000-0000-5000-8000-000000000388'::uuid, '949b29a3-ad44-59ba-8383-f7c182db0d09'::uuid, 'Yağmur''un çizelgede fark ettiği durum neden önemliydi?', 2, 4, 3, 'Hatalar sağ arka köşede toplanıyordu ve rakip servislerin çoğu da oraya geliyordu; bu, bir zayıflığın kullanıldığını gösteriyordu.',
     'Liberonun en çok sayıyı kendisi alması', 'Rakiplerin zayıf noktayı hedef alması', 'Smaçların çoğunun sol köşeye gitmesi', 'Takımın servislerinin çoğunu dışarı atması', 'B', 3),
    ('d7b50000-0000-5000-8000-000000000389'::uuid, '949b29a3-ad44-59ba-8383-f7c182db0d09'::uuid, 'Özel çalışmadan sonraki maçta ne oldu?', 1, 2, 3, 'Sonraki maçta sağ arka köşedeki hatalar yarıya indi.',
     'Takım maçı ilk sette kaybetti', 'Ceren başka bir pozisyona geçti', 'Karşılama hataları yarıya düştü', 'Rakip servis yerini değiştirdi', 'C', 4),
    ('d7b50000-0000-5000-8000-000000000390'::uuid, '949b29a3-ad44-59ba-8383-f7c182db0d09'::uuid, 'Kenardan izlemek Yağmur''a ne kazandırdı?', 2, 4, 3, 'Sahada yalnızca topu ve rakibi görürken kenarda bütün sahayı, oyuncuların yerini ve takımın zorlandığı anları görebiliyordu.',
     'Oyunu bütünüyle görebilmeyi', 'Rakip antrenörle tanışmayı', 'Topa daha sert vurabilmeyi', 'Bileğini daha çabuk iyileştirmeyi', 'A', 5),
    ('d7b50000-0000-5000-8000-000000000391'::uuid, '949b29a3-ad44-59ba-8383-f7c182db0d09'::uuid, 'Fizyoterapiste göre egzersizler neden gerekliydi?', 2, 4, 3, 'Burkulan bilek yalnız dinlenerek değil güçlendirilerek iyileşir; aksi hâlde aynı sakatlık kolayca tekrarlayabilir.',
     'Bileğin daha iyi dinlenmesi için', 'Doktordan izin raporu almak için', 'Sakatlığın yinelenmemesi için', 'Takımdaki yerini korumak için', 'C', 6),
    ('d7b50000-0000-5000-8000-000000000392'::uuid, '949b29a3-ad44-59ba-8383-f7c182db0d09'::uuid, 'Metnin ana fikri hangisidir?', 3, 5, 3, 'Yağmur sezonun çoğunu kenarda geçirdi ama tuttuğu kayıtlarla takıma en çok katkı yapanlar arasında sayıldı.',
     'Sakatlıklar sporcuların kariyerini bitirir', 'Sporda en önemli şey istatistiktir', 'Kenarda kalan oyuncu takımdan kopar', 'Oynamadan da takıma katkı verilebilir', 'D', 7),
    ('d7b50000-0000-5000-8000-000000000393'::uuid, '964eef2e-0383-56e4-8e60-2b21469b450f'::uuid, 'Yazar metne hangi örnekle başlar?', 1, 2, 2, 'Metin, önemli bir sunumun ortasında başlayan hıçkırığın insanı zor durumda bırakabileceğini söyleyerek açılır.',
     'Sunum yaparken hıçkıran biri', 'Sınavda zorlanan bir öğrenci', 'Yemekte boğazı tıkanan bir çocuk', 'Uykuda horlayan bir yetişkin', 'A', 0),
    ('d7b50000-0000-5000-8000-000000000394'::uuid, '964eef2e-0383-56e4-8e60-2b21469b450f'::uuid, 'Nefes alırken diyafram ne yapar?', 1, 2, 2, 'Nefes alırken diyafram kasılır ve aşağı iner; nefes verirken gevşeyip yükselir.',
     'Gevşeyerek yukarı çıkar', 'Kasılarak aşağı iner', 'Yana doğru genişler', 'Hiç kıpırdamadan durur', 'B', 1),
    ('d7b50000-0000-5000-8000-000000000395'::uuid, '964eef2e-0383-56e4-8e60-2b21469b450f'::uuid, 'Hıçkırıktaki "hık" sesi nasıl oluşur?', 1, 2, 2, 'İçeri çekilen hava, ses telleri arasındaki kapanan aralığa çarpar; ses boğazdan gelir.',
     'Mide aniden şişip sarsılınca', 'Akciğerler hızla boşalınca', 'Hava ses tellerine çarpınca', 'Diyafram birden gevşeyince', 'C', 2),
    ('d7b50000-0000-5000-8000-000000000396'::uuid, '964eef2e-0383-56e4-8e60-2b21469b450f'::uuid, 'Hızlı yemek yemek hıçkırığa nasıl yol açabilir?', 2, 4, 2, 'Hızlı yerken hava da yutulur, mide şişer ve hemen üstündeki diyaframı rahatsız edebilir.',
     'Yemek boğazda takılıp kalır', 'Sıcak yemek ses tellerini yakar', 'Hızlı çiğnemek çene kasını yorar', 'Şişen mide üstteki kası etkiler', 'D', 3),
    ('d7b50000-0000-5000-8000-000000000397'::uuid, '964eef2e-0383-56e4-8e60-2b21469b450f'::uuid, 'Hıçkırığın vücuda yararı konusunda ne biliniyor?', 1, 2, 2, 'Bilim insanları bunu hâlâ araştırıyor; farklı görüşler var ama kesin bir yanıt bulunamadı.',
     'Konu hâlâ yanıt beklemektedir', 'Bağışıklığı güçlendirdiği bilinir', 'Bebeklere yaradığı kanıtlandı', 'Sindirime yardım ettiği bulundu', 'A', 4),
    ('d7b50000-0000-5000-8000-000000000398'::uuid, '964eef2e-0383-56e4-8e60-2b21469b450f'::uuid, 'Ev yöntemlerinin bazı kişilerde işe yaramasının olası nedeni nedir?', 2, 4, 2, 'Metne göre bu yöntemler nefes alıp verme düzenini değiştirdiği için bazen işe yarıyor gibi görünür.',
     'Kişinin yönteme gerçekten inanması', 'Soluk alma ritmini değiştirmeleri', 'Suyun mideyi hemen serinletmesi', 'Korkunun nabzı hızlandırması', 'B', 5),
    ('d7b50000-0000-5000-8000-000000000399'::uuid, '964eef2e-0383-56e4-8e60-2b21469b450f'::uuid, 'Hangi durumda bir doktora görünmek gerekir?', 2, 4, 2, 'Hıçkırık iki günden uzun sürerse ya da uyumayı ve yemeyi zorlaştırırsa doktora gidilmelidir.',
     'Yemekten hemen sonra başlarsa', 'Gülerken ortaya çıktığında', 'Kırk sekiz saati geçtiğinde', 'Bir saat kadar sürdüğünde', 'C', 6),
    ('d7b50000-0000-5000-8000-000000000400'::uuid, '964eef2e-0383-56e4-8e60-2b21469b450f'::uuid, 'Yazar son paragrafta hıçkırığı nasıl yorumlar?', 3, 5, 2, 'Yazar "hık" sesini, vücudun aynı anda pek çok şeyi birlikte yönettiğini hatırlatan bir işaret olarak görür.',
     'Ciddi bir hastalığın erken belirtisi', 'Kolayca önlenebilecek bir alışkanlık', 'Yalnızca stresle ortaya çıkan bir tepki', 'Bedenin karmaşık işleyişine bir örnek', 'D', 7),
    ('d7b50000-0000-5000-8000-000000000401'::uuid, '9dae6fc9-fd41-53a4-8c45-3f8860ae9d90'::uuid, 'Derin''in kulüpte kalmaya karar vermesinin nedeni nedir?', 2, 4, 5, 'Cem Bey''in gökyüzüne gerçekten bakan kişinin az olduğunu söyleyen cümlesi aklına takılmıştı.',
     'Arkadaşının ondan kalmasını istemesi', 'Kulübün ödül vereceğini duyması', 'Öğretmenin bir sözünü unutamaması', 'Teleskop sahibi olmak istemesi', 'C', 0),
    ('d7b50000-0000-5000-8000-000000000402'::uuid, '9dae6fc9-fd41-53a4-8c45-3f8860ae9d90'::uuid, 'Gözlem gecesi neden kentin dışında yapıldı?', 1, 2, 5, 'Lambalardan ve binalardan göğe yayılan ışık sönük yıldızları örtüyordu; birkaç kilometre uzaklaşmak bile fark yaratıyordu.',
     'Kentte teleskop kurmak yasak olduğu için', 'Tepe Jüpiter''e daha yakın olduğu için', 'Okul bahçesi o gece ziyarete kapalı olduğu için', 'Yapay aydınlatma gökyüzünü bulandırdığı için', 'D', 1),
